quests[94449] = { id = 94449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "It's been long since ye were last tested, {name}. Ye've shown patience, aye -- but now it's time ye learned of chaos... of destruction. Fire's call is loud, and if ye're ready to pay its price, it'll speak to ye. \n\nSeek out Bruegs Kindleborn, far east in the mountains. He dwells in a cave above South Gate Outpost. He'll know if ye're truly ready.", sourceObjective = "Find Bruegs Kindleborn in Dun Morogh.", completion = "Hmm... that elder sent ye, eh? Well, a {class}'s word is solid, so I'll not argue. That means ye're ready for the next sapta. The sapta of fire. I see it in yer eyes already -- the burnin', the hunger. Ye've tasted power, and now ye want more. But mind yerself, {name}. Remember what the stone taught ye. Fire's easy to wield, but harder to master. Know when to hold back.", sourceObjectiveStatus = "unverified-source-field" }
quests[94465] = { id = 94465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Aye, ye've the strength to bear the totem o' fire, lad--but strength alone won't make ye ready.\n\nBeyond the Valley o' Kings, in the crags of Loch Modan, lies a hidden path to one o' our sacred peaks. There, Braldir Ashmantle guards the Shrine o' the Dormant Flame. \n\nTake this torch to him--it shows yer intent. Return it burnin' by the shrine's brazier, and I'll see ye earn the totem proper.", sourceObjective = "Bring the Torch of the Dormant Flame to Braldir Ashmantle in Loch Modan.", progress = "Greetin's, {name}. Ye've made it to the Shrine o' the Dormant Flame, eh? Not many do. Only those well-versed in the {class}'s path can grasp the secrets this place holds. \n\nShame ye came all this way just to be turned back--the climb's no stroll through Dun Morogh. But I'm the shrine's keeper, and I won't be lettin' just any foot trod about.", completion = "Ah, me apologies, {name}. Didn't spot the Torch in yer hand. An honor to meet ye proper.\n\nMany a wanderer climbs these heights chasin' tales of treasure or beasts, only to find naught but stone and silence. But we know better, don't we, {name}?\n\nThis shrine holds truths far deeper than the Alliance can fathom. To us, it's a sacred flame that waits to be awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[94466] = { id = 94466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Bah, ye didn't trek all this way for tales, did ye, {name}? Ye seek the Eternal Flame and the fire totem.\n\nFirst, ye'll need a sapta to bind yer spirit to the flame.\n\nI'll craft it--but I'll need two things: fire tar from Tunnel Rat Geomancers in the kobold caves up north, and a reagent pouch from a Stonesplinter Seer lurkin' in the southern hills. Dangerous work, but worthy of the flame.", sourceObjective = "Bring 1 Fire Tar and 1 Reagent Pouch to Braldir Ashmantle in Loch Modan.", progress = "Aye, I've near all I need for the fire sapta, {name}--just missin' the fire tar and the seer's pouch. The tar's carried by Tunnel Rat Geomancers in the kobold caves up north. The pouch ye'll need to wrest from a Stonesplinter seer in the southern hills. These ingredients are bound to flame, as all true saptas must be. Their elemental ties make our craft strong.", completion = "These'll do fine, {name}.\n\nFire ain't just fury and ruin--mark me words. It's life, it's forge, it's the breath o' creation. All things are bound in balance. One force tempers the other, gives it meaning. Without shadow, light's but a glare. Without flame, stone's but cold memory.\n\nMasterin' magic means knowin' when to blend, not just burn. That's true wisdom, lad.", sourceObjectiveStatus = "unverified-source-field" }
quests[94467] = { id = 94467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "The fire sapta's ready, {name}. Now ye face the flame. Use it at the shrine, then climb to the peak. There, ye'll see the spirit--he'll not strike 'til ye do, but he'll know ye see him.\n\nStrike fast, lad. The longer ye wait, the stronger he burns. When he falls, take his glowing embers and place 'em in the brazier. Light the torch and earn the fire's favor.", sourceObjective = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", progress = "The brazier stands about a third your height, with charred inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch. \n\nBlackrock mountain looms in the distance, in clear view to honor from this sacred place.", completion = "A white hot flame ignites within the bowl as you place the ember within. You can feel the magical effects of the sapta coursing through your body and the fire dances rhythmically before you.\n\nYou place the top of the torch within the basin, and it immediately catches on fire. The smoke seems to drift towards the mountain of blackrock.", sourceObjectiveStatus = "unverified-source-field" }
quests[94468] = { id = 94468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Torch firmly in hand, you turn away from the brazier and look out over Loch Modan. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to Dun Morogh in search of Bruegs Kindleborn.", sourceObjective = "Bring the Torch of Eternal Flame to Bruegs Kindleborn in Dun Morogh.", progress = "Aye, {name}? What do ye have there?", completion = "By Madoran's beard, yer spirit burns brighter than any torch I've laid eyes on, {name}--and that's somethin' to be proud of.\n\nKeep walkin' this path, and the elements'll bend to yer will. Our kin will come to ye for wisdom and guidance. So let me be the first to offer me hearty congratulations -- and present ye with yer newest totem. Ye've earned it, flameborn.", sourceObjectiveStatus = "unverified-source-field" }
quests[94472] = { id = 94472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth Sapta", sourceObjective = "Speak to Teo Hammerstorm for another Earth Sapta.", completion = "Take this and remember, it is sacred.", sourceObjectiveStatus = "unverified-source-field" }
quests[94473] = { id = 94473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Sapta", sourceObjective = "Speak to Braldir Ashmantle for another Fire Sapta", completion = "May fire burn within your heart, Ukko.\n\nThe elements await you.", sourceObjectiveStatus = "unverified-source-field" }
quests[94484] = { id = 94484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnerving Silence", description = "A moment, if you will {name}. Are you headed towards Shadowgale Forest? There is a druid conclave there in a cave to the northeast. I have been waiting on word from them but their correspondence is long overdue.\n\nWith Ban'aethall in ruins and all the unrest lately I worry something dire may have happened. Please, if you are able go, seek out Elegael Thornpaw and put my mind at ease.", sourceObjective = "Find and speak with Elegael Thornpaw in the northeastern part of Shadowgale Forest.", completion = "Thank goodness our message got to Lotheluum. Wait, where are the rest of the reinforcements? Surely it is not just you they sent?\n\n<Elegael pales as you relay your conversation with Lotheluum.>\n\nSo the message did not get through. We are in dire straights indeed then.\n\nIt seems we must handle this on our own. Time is of the essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[94485] = { id = 94485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of the Lady", description = "If we are to save my fellows in the Nightclaw Den, I am going to need some ingredients for a poultice. The first and most important is a spindly moss called Lady's Tear. It typically grows on the base of the trees here in Shadowgale.\n\nThis moss secretes a sticky substance that acts as an antiseptic and is perfect for binding open wounds. I have gathered what little I can reach but I know there is more in this forest.\n\nGo and be swift. We are going to need a lot if the injured I left behind still live.", sourceObjective = "Collect 8 Lady's Tear Moss.", progress = "Have you found the Lady's Tear?", completion = "<Elegael takes the sticky mound of moss from you with a weak smile.>\n\nThank you, {name}, you have done well. This is exactly what we need.", sourceObjectiveStatus = "unverified-source-field" }
quests[94486] = { id = 94486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Binding", description = "The other ingredient I need for the poultice is feathers from the Shadowgale shrieklings that roam this forest. In their juvenile form, the shrieklings have insulative feathers which would be ideal to put over the moss. These feathers will prevent the antiseptic sap from drying out and will provide at least some protection against the elements.\n\nBe warned, the shrieklings are normally docile but they have been incredibly hostile of late. Their large talons can easily disembowel you if you aren't careful.", sourceObjective = "Collect 20 feathers from the Shadowgale Shrieklings in Shadowgale Forest.", progress = "It deeply saddens me to ask you to kill the young shrieklings, but with the rise in their aggression it is for the best. We can only handle so many emergencies at a time.", completion = "Thank you for these. I will be sure to use every feather so their sacrifice will not be in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[94487] = { id = 94487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwanted and Unworthy", description = "The Al'aketh Cultists ambushed us with no warning, though their motives remain a mystery to me. I knew these cultists had clouds in-between their ears, but I never imagined they would upset the delicate balance here on Zephras with such brutality. Go, slay as many as you can and take their heirlooms if they wear any.\n\n<Elegael spits.>\n\nThese storm cursed cultists don't deserve to be called shen'dorei. The beasts of the forest can have their bodies. Their ashes don't deserve the winds.", sourceObjective = "Collect 10 Bloodied Heirlooms from Al'Aketh Footsoldiers and Al'Aketh Stormchasers in the Shadowgale Forest.", progress = "I will make the cult pay for every drop of druid blood they have spilled this day.", completion = "<Elegael looks down at the collection of bloodied heirlooms with distress.>\n\nSo many young lives with so much potential now gone forever. Thank you for returning these, {class}.\n\nI will hold onto them for safe keeping until I am able to take them to the High Elder. There they can go back into the collection and await the next and perhaps more worthy generation to come of age.", sourceObjectiveStatus = "unverified-source-field" }
quests[94488] = { id = 94488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ties That Bind", description = "The reason for cultists presence here still baffles me, but I smell a familiar scent over the bloodshed.\n\nOne of our circle druids, Haalien, disappeared months back. It appears he's thrown his sorry hide in with the cultists.\n\nShow him what happens when he spills the blood of his kin! Take his head and return it to me.", sourceObjective = "Kill Commander Haalien and bring his head to Elegael Thornpaw in the Shadowgale Forest.", progress = "Are our brethren's lives truly worth so little to you, Haalien?", completion = "<Elegael grimaces at the severed head, but nods curtly.>\n\nThank you, {name}. No matter how much rage I have within me, it would have been difficult to strike down my own cousin.\n\nDo not mourn for him. His ignorance and malice has killed many innocents this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[94489] = { id = 94489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wounds of Betrayal", description = "I have finished the poultices. Quickly, take them to the druids in the cave, north just across the clearing. I know my brethren are in much more dire condition than I. They are likely too injured to heal their own wounds. There are so few of us shen'dorei druids that every life is precious.\n\nBefore you go, I have a selfish request. My mate, Jorel Windsinger was in dire condition when I left. Please, see to his wounds if he still lives.", sourceObjective = "Enter the Nightfang Den and heal 7 druids and find Jorel Windsinger in Shadowgale Forest.", progress = "{class}! You have returned. Were you able to reach my brothers and sisters? Did you find Jorel?", completion = "<Elegael's face pales as you relay the fate of Jorel and the condition of the rest of the druids.>\n\nNo... no! This is far worse than I had--\n\n<Elegael chokes back a sob, and grits her teeth letting out a pained snarl.>\n\nThey will pay. They will ALL pay. Anyone who allies with the Al'aketh will feel my wrath! This I swear.", sourceObjectiveStatus = "unverified-source-field" }
quests[94490] = { id = 94490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ripped Missive", description = "<Tucked behind one of Haalien's bracers is a note that's been slightly torn and bloodstained in your fight. It looks like it contains useful information for about the cultist motivations for the attack on the druid den. Elegael would be interested in this intel.>", sourceObjective = "Bring the Ripped Missive to Elegael Thornpaw in the Shadowgale Forest.\n\nProvided item:", completion = "They were here for the pylon? But to what end? We were not the original reason for their attack?\n\n<Elegael trails off shaking with rage as she reads.>\n\nThey murdered my people because we were an inconvenience! I shall tear apart every cultist with my fangs! I will make sure none leave this place with their lives.\n\nGo, swiftly! If the orders truly originated in Valanaar, it means it is likely a traitor hiding there. Give the missive to Lotheluum in Valannar and tell him what has transpired.", sourceObjectiveStatus = "unverified-source-field" }
quests[94491] = { id = 94491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Den", description = "It would appear that there is a correspondent hiding somewhere in Valanaar feeding information to the cult. I am clearly in no shape to make the journey, but Lotheluum needs to know what transpired here.\n\nHe should also know the fate of those who are no longer with us. Thanks to your help I think we can handle the rest of the situation from here, thought the damage has been done.\n\nPlease go swiftly, {name}. I hope our paths will cross again someday. Until then, I have cultists to slay.", sourceObjective = "Give the missive to Lotheluum in Valannar and tell him what has transpired.\n\nProvided item:", completion = "<Lotheluum wears a look of genuine terror as you recount the events from the druid den.>\n\nI--I'm sorry, {name}. I need just a moment. There are no words I possess that can describe the loss.\n\nThis is grave news indeed. If this missive is not fabricated, then we indeed have at best an accomplice and at worst a traitor here in Valanaar. I will take this to the High Elder immediately! I will not let my fellows sacrifice be in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[94493] = { id = 94493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sacrifice in Vain", description = "Thank goodness our message got to Lotheluum. Wait, where are the rest of the reinforcements? Surely it is not just you they sent?\n\n<Elegael pales as you explain yourself.>\n\nSo the message did not get to Valanaar. We are in dire straights indeed then.\n\n<Elegael sighs deeply then looks resolute.>\n\nThen we must handle this on our own. Time is of the essence.", sourceObjective = "Speak with Elegael Thornpaw in the northeastern part of Shadowgale Forest.", completion = "The Al'aketh Cultists ambushed us with little to no warning. Many inside my den lay wounded or dying. I had attempted to send a message to Valanaar but it appears my efforts were in vain.\n\nPlease, if you have come here I beg for your help. I don't know how much longer my fellows will be able to survive this onslaught.", sourceObjectiveStatus = "unverified-source-field" }
quests[94494] = { id = 94494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Long has it been since ye were last tested, {name}. Ye have shown patience thus far in yer studies, but the time has come for ye to learn about the purity of water.\n\nSeek out Norric Lochthane in Loch Modan. He is along the north western edge o' the lake, south of Stonewrought Dam. Ye  will find him there at his burrow hut. Good luck to ye, {name}.", sourceObjective = "Find Norric Lochthane in Loch Modan.", completion = "The wind's rushin' at yer back, the stone's firm beneath yer boots, and the fire in yer belly's burnin' bright. Aye, it's time ye learned the truth o' water's purity. Yer path's been long, but it's yer spirit that'll carry ye further still. Now, go on, take that first step. The mountain waits for no one.", sourceObjectiveStatus = "unverified-source-field" }
quests[94495] = { id = 94495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "If there's one truth ye need to learn about water, it's this: water means rebirth. It carves stone, cleanses filth, and heals the weary -- but only when it's pure. Taint it, and it'll ruin all it touches.\n\nIf ye seek the water sapta, find Hervdana Saegrund in the Wetlands. Her family dwells in a cave beneath the southern falls.\n\nGo on then, don't let the river outrun ye.", sourceObjective = "Find Hervdana Saegrund in the Wetlands.", completion = "Aye, I see it in yer eyes, {race}. You're wonderin' what kind o' soul chooses to live out here, deep in the Wetlands, with Dark Iron scum lurkin' about and nary a guard in sight. Well, we all have our reasons, love. \n\nBut the real question is, what brings you to our home? Out here at the edge of the falls, I reckon we both know the answer to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[94497] = { id = 94497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Ah, so ye've come seekin' the sapta, have ye? Well then, listen close, love. To find understandin' and earn the sapta, ye must seek water in its various forms. As ye gather the samples, keep yer eyes open. Watch the beasts that guard it, the land it nourishes, and how it changes lives.\n\nWe'll start simple: fill this skin at the base o' the falls, where the fresh meets the brackish. Go on now, and mind the marsh.", sourceObjective = "Fill the Empty Brown Waterskin at the bottom of the waterfalls below Hervdana's cave and return it to her in the Wetlands.", progress = "I'm nearly ready to send ye off on the rest o' yer tasks. But tell me, have ye filled the skin yet? The ocean brings life, aye -- but it carries sediment, minerals, and energies far different from the snowmelt and springwater of the highlands. Where sea and spring meet, there's wisdom to be found.", completion = "Glad ye managed to steer clear o' the Dark Iron. Shame they've crept so far north--makes ye wonder what dwarfkind could do if the clans ever stopped squabblin' and worked as one.\n\nStill, the tides rise high when the moons are strong, and the seawater floods the marsh. It's here that we study our estuary water.\n\nThank ye for this sacred offering, it marks the beginning of your stage as a vessel--one who seeks the waters' wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[94499] = { id = 94499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Aye, Redridge drinks deep from Lake Everstill, but by the time the waters tumble down Stonewatch Falls, somethin' has seeped in. The murlocs down there are big, twisted brutes. Not like the ones ye find here or in the Loch. Lucky for the townsfolk they keep to the base o' the falls.\n\nBring a sampling to me. I've a mind to find out if it's magic, venom, or somethin' worse that's taintin' the waters near that old fort.", sourceObjective = "Fill the Empty Red Waterskin at Stonewatch Falls near the Nightcrawler Murlocs and return to Hervdana Saegrund in the Wetlands.", progress = "The folk o' Lakeshire don't ken how good they've got it -- fresh water flowin' right at their boots, keepin' their nets full, their crops green, and their coin purses jinglin'. Even when the kingdom's guard can barely spare a lad with a sword, they've got Everstill watchin' over 'em.", completion = "Aye, this is good water, {name}. The magic used by the shadowseers in the region must be changin' the murlocs. Nothin' but pure water, this be. Yer dedication to the task at hand and abilities to seek out that which is needed proves you're ready for the next stage of your journey.\n\nOne more sample is all I need to create the reagent needed for your sapta. Norric will be pleased as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[94500] = { id = 94500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Take this waterskin and journey deep into the emerald shade o' Ashenvale. Astranaar rests cradled by waters untouched by corruption. Ruins litter the bed o' the lake, hinting at a bygone era. Bring back a sample from the lake. Pure, ancient, and possibly enchanted water.\n\nIt's the last liquid I need before I send ye back to Norric.\n\nBoard the boat in Menethil to Auberdine, it stops in Southshore on the way over.\n\nAnd mind yerself... the forest's got eyes, and they don't blink.", sourceObjective = "Fill the Unfilled Blue Waterskin at the waters of Astranaar in Ashenvale and return to Hervdana Saegrund in the Wetlands.", progress = "Do you have the water yet, {name}? If ye haven't made the trek to Kalimdor yet, be careful.", completion = "Well done, {name}! With all three samples in hand, I'll brew ye a vial o' water so pure it'd make the mountains weep. It's the final piece for yer rite o' passage. I'm proud to call ye kin, {name}. Ye've done {class} proud, and I look forward to hearing yer tales in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[94501] = { id = 94501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Norric will have one more task for ye before rewarding ye with the water totem rites. The vial of water I've given ye is necessary for whatever that task is. Go now and find him. We shall meet again some day.", sourceObjective = "Bring the Vial of Purest Water to Norric Lochthane in Loch Modan.", progress = "Hello again, {name}. Yer looking well. \n\nWhat brings you back to me so soon?", completion = "Ahh, water blessed by Hervdana herself, and gathered by your own hands? A gift indeed. \n\nThese vials shall birth your sapta, letting you glimpse the water spirits at Stendel's Pond, near Moonbrook. The last few drops of the water have an equally important purpose... waste not even a cork stopper dampened with sacred water.", sourceObjectiveStatus = "unverified-source-field" }
quests[94502] = { id = 94502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "In Westfall, outside o' Moonbrook lies Stendel's Pond. Once a pure spring, now touched by dark forces. The spirits there 'ave gone silent. \n\nYe must face the corruption that fouls the waters. Take its bracers and the last drops o' Hervdana's potion, then place 'em on the shrine. That'll call forth a spirit, cleansed and true. Speak with it, learn what ye can.\n\nBring me proof the deed's done, and I'll grant ye the totem.", sourceObjective = "Cleanse the corruption at Stendel's Pond in Westfall.\nReturn to Norric in Loch Modan when finished.", progress = "The shrine stands aged and forgotten, cloaked in dust and cobwebs. The pond beside it lies eerily still, its surface untouched by wind or life. Scattered along the shore are the bones of beasts once burdened by labor. The water's murky sheen raises a troubling question--has it been poisoned by the surrounding malaise, or is it the very source of it?", completion = "You place the bracers atop the shrine and then pour the remaining drops of Norric's potion into dry stone. You begin to incant the simple words Norric taught you and the droplets vaporize atop the stone within the bindings....", sourceObjectiveStatus = "unverified-source-field" }
quests[94503] = { id = 94503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Light erupts as the final word leaves your lips. The hiss of water turning to mist fades into silence, and your senses reel as the corrupt spirits around you unravel, their essence scattered like ash in the wind.", sourceObjective = "Speak to the Minor Manifestation of Water in Westfall.", completion = "Thanks to you. Thanks to the shamans.\n\nCorruption ebbs but life continues to wane. Up to shamans to protect life.", sourceObjectiveStatus = "unverified-source-field" }
quests[94505] = { id = 94505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.", sourceObjective = "Bring the Shard of Water to Norric Lochthane in Loch Modan.", progress = "How fared your journey to Westfall? Success there is hard to measure, but even small victories carry weight.", completion = "Aye, this is the proof I asked for, and ye've done well, {name}. I'm proud to be the first to offer my congratulations--and yer water totem. Use it wisely, and may fortune walk beside ye.\n\nYer next trial won't come soon, so take this time to learn. Pure water heals, aye, but its gifts go far beyond mending wounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[94568] = { id = 94568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult's True Plans", description = "The turncoat clearly was afraid of the what the cult had planned, enough so to defect and seek our aid. It's truly unfortunate that he is dead and took his secrets to the grave with him.\n\nWe must discuss this further to determine our next steps.", sourceObjective = "Speak with Talaanis Shadowsong and observe the conversation.", progress = "That turncoat risked everything to escape the cult and bring us this crystal...", completion = "We could try and send peacekeepers to directly engage the cult forces, but we would not fare well against them in open battle.\n\nWe are going to need a different approach.", sourceObjectiveStatus = "unverified-source-field" }
quests[94616] = { id = 94616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Sapta", sourceObjective = "Take the water sapta and find the tainted pond water in Westfall, {name}. I have great faith in your abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[94638] = { id = 94638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength and Mercy", description = "You have come to me in hopes of learning to take a shape of strength. I have a task for you, though it lays heavy on my heart.\n\nMy mate, Ur'endra, has lost herself to madness and has begun to attack her own kin. Without the magic of the winds, many creatures have begun to lose themselves... Ur'endra included. She makes her lair in a cave to the west of here, in the bluffs along the border between the Shen'dar Highlands and the Gustberry Lowlands.\n\nEnd her suffering and I shall grant you my blessing.", sourceObjective = "Find and kill Ur'endra in the Shen'dar Highlands.", progress = "What I ask of you is no easy task. Take heart in your courage and return to me when the deed is done.", completion = "The agony I feel over her loss is immeasurable, but it is what is necessary for the balance. You have demonstrated a resolve to persevere, even when a terrible price is asked.\n\nYou have done well, {class}. I shall grant you the blessing to take on the shape of my kin. Be a beacon for those that lack the strength to persevere and a defender of those in need.\n\nGo now, and embrace the way of the claw, child.", sourceObjectiveStatus = "unverified-source-field" }
quests[94773] = { id = 94773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", sourceObjective = "You have done the Light a great service by becoming a shining example to those who travel in these dangerous lands and beyond. Please, accept this lesson as a thanks for all you've done.", sourceObjectiveStatus = "unverified-source-field" }
quests[94774] = { id = 94774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "You've caught the attention of our superiors, {name}. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[94775] = { id = 94775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "Elune bless you, good {race}. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.You will learn:", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94776] = { id = 94776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "Time's come for you to head to Stormwind, {name}. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.You will learn:", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94777] = { id = 94777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "Just a short time ago, one of your priests was here looking for you, {race}. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good {race}.You will learn:", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94778] = { id = 94778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "You're needed in Stormwind, {name}. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, {name}.You will learn:", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94779] = { id = 94779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Grace", description = "Praise be to Elune, and to your Light, {name}.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.You will learn:", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94789] = { id = 94789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "The winds o' Azeroth greet ye, and soon ye'll stand among some o' our mightiest kin. I'm proud to see how far ye've come--your future looks bright indeed.\n\nThe element o' air's a tricky one to master, but I've faith your skill will see ye through any challenge.\n\nMake your way north into Arathi Highlands. In its northern hills, you'll find Veyric Thundervein. He'll teach ye more.", sourceObjective = "Find Veyric Thundervein in Arathi Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[94792] = { id = 94792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Many hunters prefer to travel with animal companions. With a beast at your side, you will find that you can survive even the most dangerous of circumstances. As they say, everything is easier with a friend. However, obtaining an animal companion is something that must be done with care. The balance of nature is delicate, and must always be respected.\n\nTake this Taming Rod with you to the forest. With it, you will be able to tame a Rockhide Boar and practice your skills as a hunter.", sourceObjective = "Use the Taming Rod to tame a Rockhide Boar. Practice your skills, then return the Taming Rod to Josephine Carson.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner.", sourceObjectiveStatus = "unverified-source-field" }
quests[94793] = { id = 94793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than Isaac Chan, a lifelong woodsman. He will give you the ability to train your new pet.\n\nGo with the winds, young {class}.", sourceObjective = "Speak to Isaac Chan in Goldshire.", completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date.", sourceObjectiveStatus = "unverified-source-field" }
quests[94817] = { id = 94817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", sourceObjective = "You took your time arriving, {name}. But you can be excused given your dedicated service to the Light. Please pay close attention to this lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[94818] = { id = 94818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contingency Plan", sourceObjective = "Continue your service to the Light and you will become a great {class}, {name}. Maintain your vigilance and dedication!\n\nYou are ready for your next lesson in service.", sourceObjectiveStatus = "unverified-source-field" }
quests[94819] = { id = 94819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contingency Plan", description = "{name}, your High Priestess Mims would have an audience with you in Ironforge. Make haste, my clever friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Mims should still be in the Mystic Ward once you reach the city. She will be waiting.", sourceObjective = "Speak to High Priestess Mims in Ironforge.", completion = "Continue your service to the Light and you will become a great {class}, {name}. Maintain your vigilance and dedication!\n\nYou are ready for your next lesson in service.", sourceObjectiveStatus = "unverified-source-field" }
quests[94820] = { id = 94820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contingency Plan", description = "Your race is so very clever, {name}. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to reclaiming your city, but with the burden of keeping your families safe in exile. That yearning for home must weigh heavily on you.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priestess Mims in the Mystic Ward. I would not keep her waiting. May Elune guide your travels.You will learn:", sourceObjective = "Speak to High Priestess Mims in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[94821] = { id = 94821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "A priest recently visited our halls seeking you out, young {race}. He said that he was on a mission to find you and that you should return to the Hall of Mysteries in Ironforge as soon as possible. When you arrive, seek out High Priestess Mims--she will tell you more.\n\nThe Light be with you, {name}.", sourceObjective = "Speak to High Priestess Mims in Ironforge.", completion = "You took your time arriving, {name}. But you can be excused given your dedicated service to the Light. Please pay close attention to this lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[94822] = { id = 94822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "You've caught the attention of our superiors, {name}. They've asked you travel to the Hall of Mysteries in Ironforge as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Mims. She will be able to guide you further. Good luck, and may the Light be with you.", sourceObjective = "Speak to High Priestess Mims in Ironforge.", completion = "You took your time arriving, Cub. But you can be excused given your dedicated service to the Light. Please pay close attention to this lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[94823] = { id = 94823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "Elune bless you, good {race}. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Hall of Mysteries as soon as possible to speak with High Priestess Mims. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.You will learn:", sourceObjective = "Speak to High Priestess Mims in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[94824] = { id = 94824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "Time's come for you to head to Stormwind, {name}. High Priestess Mims in the Hall of Mysteries commands you to come speak with her. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.", sourceObjective = "Speak to High Priestess Mims in Ironforge.", completion = "You took your time arriving, Papi. But you can be excused given your dedicated service to the Light. Please pay close attention to this lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[94825] = { id = 94825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "Just a short time ago, one of your priests was here looking for you, {race}. He said that if I were to see you, I should direct you towards the Hall of Mysteries. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good {race}.You will learn:", sourceObjective = "Speak to High Priestess Mims in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[94826] = { id = 94826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confounding Flash", description = "Praise be to Elune, and to your Light, {name}.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out your High Priestess for further training.You will learn:", sourceObjective = "Speak to High Priestess Mims in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[94863] = { id = 94863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You've alraedy mastered taming a boar, now it's time for the next lesson. The forest holds fiercer companions, and with care, you can earn their trust.\n\nTake this Taming Rod and seek out a Gray Forest Wolf. Remember, nature's balance must be respected. Prove your skill as a hunter once more.", sourceObjective = "Use the Taming Rod to tame a Gray Forest Wolf. Practice your skills, then return the Taming Rod to Josephine Carson.", progress = "With learning, {name}, comes mastery.", completion = "Well done, {name}! You're quite in tune with the beast.", sourceObjectiveStatus = "unverified-source-field" }
quests[94864] = { id = 94864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You've proven yourself by taming a boar and a wolf, now it's time for your final challenge. Elwynn's balance depends on respect and skill. Take this Taming Rod and seek out a Young Forest Bear. Show that you can earn the trust of even the mightiest companion. \n\nCompleting this lesson will deepen your attunement to beasts.", sourceObjective = "Use the Taming Rod to tame a Young Forest Bear. Practice your skills, then return the Taming Rod to Josephine Carson.", progress = "Go forth, {name}, and tame the burliest of Elwynn beasts.", completion = "The brawn of the forest. Brave work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[94872] = { id = 94872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Friendship: Magram", description = "The fierce Magram are undoubtedly winning the war of territories at the moment. While we can all be thankful the clashes haven't erupted too frequently throughout the desert, every day their village just to the east grows a little bigger; their soldiers a little bolder.\n\nI worry gravely about the consequences of an unchecked Magram clan, but I cannot deny their potential as an ally.\n\nIf you wish to earn their trust, offer this sack of totems to their quartermaster, but be careful.", sourceObjective = "Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[94873] = { id = 94873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Friendship: Gelkis", description = "Either dominant centaur clan is likely to pose a good ally, but I ought to offer a word of caution regarding the Gelkis.\n\nI have trustworthy intel that suggests, between the Magram and the Gelkis, the latter are very much on the losing side. This may work to our advantage--desperation may push the isolated clan into opening up to outside help.\n\nI have prepared a tote of totems for you to take to their quartermaster, assuming they have one, in Gelkis Village. This may work in our favor.", sourceObjective = "Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[94896] = { id = 94896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid For The Refugees", description = "You look like a capable adventurer. Do you happen to be headed towards Shadowgale Forest? Ban'aethal lies deep in the forest; that's where we're all from.\n\n<Ealaane gestures to the other refugees.>\n\nWe've recently had to evacuate Ban'aethal, as it began to fall into the sky. It was sudden and in the middle of the night. If you are headed that way, would you please look for any belongings left behind? The forest and village are far too dangerous for us to return to now.", sourceObjective = "Collect 8 Abandoned Belongings from the ruins of Ban'aethal.", progress = "So many of us left with nothing more than the clothes on our backs. Any belongings you might recover would be cherished.", completion = "Thank you, {class}, you have done a great kindness to us refugees this day. I will make sure to return these to their owners. At least it gives us a place to start over from.", sourceObjectiveStatus = "unverified-source-field" }
quests[94897] = { id = 94897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of a Loved One", description = "If you are traveling to Ban'aethal, I have a selfish request. My love, Resaan... I believe is no longer a part of this world. He had tried to go back to get supplies even though I begged him to stay. It has been over a week already and I fear the worst.\n\nPlease, if you find him bring him home. If he has perished then I beg you to please bring me his heirloom.", sourceObjective = "Find Resaan in the Ruins of Ban'aethal.", progress = "Have you any news of Resaan? Please, {class}, the wait is hard to endure after everything that has happened.", completion = "<Ealaane's eyes well with tears.>\n\nOh, Resaan my love. What will become of us now? There was so much... it feels as if our lives together had just started.\n\nThank you, {class}. The world is cruel to take both my home and my love from me. At least his heirloom will give me some closure.", sourceObjectiveStatus = "unverified-source-field" }
quests[94898] = { id = 94898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violent Winds (Temp Disabled)", description = "When our home started to fall into the sky that fateful night, its as if the elements themselves were waiting to consume us. Wind spirits began appearing as we were fleeing, and to our dismay they began attacking the fleeing survivors.\n\nWe lost many villagers to the sky, but even more to the relentless anger of those wind spirits. I don't know if it was our village falling into the sky, but they are extremely dangerous.\n\nIf you are able, please put them to rest.", sourceObjective = "Slay 10 Wind Hollows.", sourceObjectiveStatus = "unverified-source-field" }
quests[94901] = { id = 94901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopping Helpers" }
quests[94902] = { id = 94902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valanaar Vintages" }
quests[94911] = { id = 94911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Child of Nature", description = "Greetings, young {race}. I can see that you have much promise in the druidic arts. There is one who you may want to speak with in the city of Thunder Bluff by the name of Turak Runetotem. He will teach you how to reach the stronghold of the Cenarion Circle on Kalimdor, Moonglade. \n\nYou will be welcomed there, and the druids of the circle will impart their knowledge upon you. \n\nAs your people would say--go with the wind's blessing, young one. I wish you good fortune in your adventures.", sourceObjective = "Speak with Turak Runetotem in Thunder Bluff.", completion = "A high elf, speaking to me... in Thunder Bluff. Will wonders never cease?\n\nWell, shaper of wind, let me join our Earthen Ring brothers and sisters in welcoming you to Azeroth. My fellow druids of the Cenarion Circle have much wisdom to impart upon you, child of nature.", sourceObjectiveStatus = "unverified-source-field" }
quests[94912] = { id = 94912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Child of Nature", description = "Greetings, young {class}. \n\nHave you heard of the Cenarion Circle? I'd expect not. They are an ancient order of naturalists and practitioners of the druidic arts, much like yourself. In the city of Stormwind you'll find a night elf by the name of Sheldras Moontree. He will teach you how to reach the stronghold of the Cenarion Circle on Kalimdor, a place called Moonglade.\n\nGo now. You have much to learn if you wish to save your home.", sourceObjective = "Speak with Sheldras Moontree in Stormwind.", completion = "Greetings, fellow {class}. It pleases me to meet a fellow {class} from among the Skyborne, and to be among the first to welcome you to Azeroth.\n\nI think you will find that my fellow druids of the Cenarion Circle have much wisdom to impart upon you, child of nature.", sourceObjectiveStatus = "unverified-source-field" }
quests[94913] = { id = 94913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade", description = "All druids are welcomed to the sacred lands of Moonglade.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there. I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson here on Azeroth, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid.", sourceObjective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", completion = "Ah I see that you have already mastered the form of the Bear. Good, good. You are well on your way, young {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[94914] = { id = 94914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade", description = "All druids are welcomed to the sacred lands of Moonglade.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there. I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson here on Azeroth, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid.", sourceObjective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", completion = "Ah I see that you have already mastered the form of the Bear. Good, good. You are well on your way, young {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[94946] = { id = 94946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magical City of Dalaran", description = "I had intended to be the first of us to step foot onto Azeroth, but recent events with the cult have changed my plans. As a result, I will be remaining here in Valanaar for a time. Fret not though, we have several mages awaiting our people's arrival in Dalaran. I'd encourage you to explore Azeroth while we set our affairs in order here. We will call upon agents such as yourself when you are needed.\n\nWhen you are ready, please proceed to the dock just outside this lodge and board the skycutter ship there.", sourceObjective = "Take the skycutter ship from Zephras Isle to Dalaran City and speak with Danaaris Stargale when you arrive.", completion = "Ah, you've made it. Wonderful. It's going to take us some time to get ourselves established here, so you may want to take some time to explore the city. Be warned however, try not to venture too far from the safety of the city proper.  \n\nAs idyllic as this new land appears, it can be extremely dangerous to wander outside of Dalaran without appropriate preparation and experience.", sourceObjectiveStatus = "unverified-source-field" }
quests[94947] = { id = 94947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Azeroth", description = "Its a big world down here, and we need our people to start branching out to explore it. That's where you come in.\n\nThe Kirin Tor is a member of an \"Alliance\" of like-minded nations. The de-facto heart of this alliance is the city of Stormwind to the south. Elaadrin has asked me to find someone to travel to Stormwind and meet with the regent lord there, a human named Bolvar Fordragon.\n\nWhen you are ready, the Kirin Tor mages have set up a special portal for the High Order to use to access Stormwind.", sourceObjective = "Take the Skyborne Portal to Stormwind and report to Bolvar Fordragon in Stormwind Keep.", completion = "Well met, {class}. I am Bolvar Fordragon, regent to the throne of Stormwind.\n\nA Kirin Tor messenger told me to expect an emissary from the High Order, and here you stand. It's been some time since a high elf has stood in this throne room, but I am glad to accept you now as a guest.\n\nOn behalf of the King, I welcome you to Stormwind and give you leave to travel freely through alliance lands. Welcome to Azeroth, Skyborne.", sourceObjectiveStatus = "unverified-source-field" }
quests[94978] = { id = 94978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Every hunter begins by learning the bond between beast and master. This is your first challenge. In time, you'll tame creatures from every corner of the world, but for now, start with our rivers and lakes on Zephras. \n\nTake this Taming Rod and seek out a Windsong Crawler.\n\nShow that you can earn its trust, and begin your path toward true mastery.", sourceObjective = "Use the Taming Rod to tame a Windsong Crawler found near bodies of water. \nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Well tamed, {name}! You are becoming adept already.", sourceObjectiveStatus = "unverified-source-field" }
quests[94979] = { id = 94979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You've proven you can tame the river's crawler, now it's time to test your skill on open ground. The plains of Zephras echo with the cries of the Galestrider, a proud, winged hunter that runs like the wind.\n\nTake this Taming Rod and seek one out. Travel to the lowlands and earn its trust.\n\nShow you're ready for the trials yet to come.", sourceObjective = "Use the Taming Rod to tame an Ornery Galestrider in the Gustberry Lowlands. \nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "You're back already! Impressive speed, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[95034] = { id = 95034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Debt", description = "I think you should know that it wasn't actually the Gnolls who attacked us on the road.\n\nWe were actually attacked by a giant, wolf-like creature that I now know as a \"worgen\". It dispatched our guards and came for me, but Banon threw himself in its path. I managed to get a spell off which startled the creature, causing it to flee, but Banon was already badly bitten. He insisted I leave him there but I refused.\n\nWe were limping back here when the gnolls found us. What came next was terrifying...", sourceObjective = "Speak with Lumina Windsinger in the Sepulcher.", completion = "So now you understand. At the very end of his strength after being pierced by a dozen gnoll blades, he reared up to strike me. In that final moment we locked eyes, and I could tell he still knew who he was and that he recognized me. He knew what was happening but he had no control over himself. That was the worst part.\n\nIf such a thing is possible, I will see the creature that doomed him dead so that it can never visit this horror on another living thing. I swear it upon the sky above.", sourceObjectiveStatus = "unverified-source-field" }
quests[95036] = { id = 95036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Moon-Kissed Blade", description = "Trevan tells me that the worgen are a major threat to the citizens of Silverpine Forest. Despite their strength and resilience they can be killed, but there is one in particular that just doesn't ever seem to stay dead due to unknown magic.\n\nThat's the one that attacked us. He is known as Old Fire-Eye and he is the biggest and meanest of their kind. To put him down, we'll need a special kind of weapon.\n\nSpeak with Trevan and he will supply you with a list of what is needed to forge such a weapon.", sourceObjective = "Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", progress = "Trust in the light to guide your blade. However, the light needs a good blade to guide.", completion = "Now that we've got the materials we need, we just need a smith to craft the blade for us. I think I know just such a smith.", sourceObjectiveStatus = "unverified-source-field" }
quests[95041] = { id = 95041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Hoarders", description = "Before we fled Gnomeregan, I made a hard copy of my family's archives. Arcanotechnical field equations, Second War submarine hull designs, Grandma Quikswitch's chili recipe... our greatest accomplishments are in those files.\n\nIt wasn't until we reached Ironforge that I found a hole in my pack! Several punch cards are gone, and without them the data's too scrambled to recover.\n\nThe cards must be buried in the snow, somewhere outside Gnomeregan. Could you find them? I know it's a long shot...", sourceObjective = "Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge.", progress = "How is the data retrieval progressing?", completion = "These cards seem a bit damp... but I can work with this! Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[95042] = { id = 95042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Kor Gem", description = "A Forsaken paladin... here in Ashenvale? Amusing. \n\nSo you seek a Kor Gem? Unsurprising as these are sometimes employed to empower magical weapons and implements by the paladins of the alliance. Why should a fallen paladin like you be any different?\n\nIf you truly desire one of the gems, then you must head north to the ruins known as Blackfathom Deeps. The naga who still use the gems are down below. Do not go alone, {class}.", sourceObjective = "Bring a Kor Gem to Ulric Frostveil in Ashenvale.", progress = "Kor gems can be used for great acts of evil. Far be it from me to judge if your intentions are pure. It matters not to me.", completion = "You'll no doubt notice the corruption that permeates this gem. For your purposes, The magic needed to dispel the evil that the naga witches have infused into the gem is rather simple. A shame really, there's much one could learn from such powers.\n\nI don't suppose you'd be willing to abandon whatever quest caused you seek this gem, and sell it to me instead? It could prove valuable to my... academic pursuits.", sourceObjectiveStatus = "unverified-source-field" }
quests[95065] = { id = 95065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishin' Time", description = "What a view... Best an old man can ask for.\n\nThe fish sure are bitin' now, though I'm down to my last bait. I don't suppose you have any spare fishing supplies on you? Of course not, forgive me. I get so excited at the thought of casting another line it didn't dawn on me I may be one of the few carrying supplies everywhere I go.\n\nWould you be able to help refresh my stock? Catherine Leland has an assortment of fishing goods just west of the Trade District along the canals. Tell her old Gray sent you.", sourceObjective = "Bring 1 Shiny Bauble and 3 Nightcrawlers to Gilbert Gray at the harbor in Stormwind.", progress = "Did you get the fishing supplies?", completion = "Great timing! Caught a big one with my last bait. Great day so far. They're really biting out here!\n\nTell you what, since you were kind enough to keep this old man in business how about a few fish for the road?", sourceObjectiveStatus = "unverified-source-field" }
quests[95111] = { id = 95111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Underrated Talent", description = "In Tarren Mill there is a weaponsmith known as Ott. By all accounts he is an unremarkable smith, selling simple blades to travelers. I purchased a sword from him myself, and when I took it to the undercity for maintenance some time later, the smiths there were surprised at its quality. They assumed it came from a well known master smith, but no, it was just Ott.\n\nI'd like to give this orc a chance to do something truly special. Take the materials to Ott in Tarren Mill and offer him the commission.", sourceObjective = "Speak with Ott and ask him to forge your blade.", progress = "Are you in need of a blade, {class}?", completion = "Interesting. I don't think anyone has ever asked me to actually carry out a custom commission for them. Mostly I just make humble, functional weapons in my own style. It's not much, but its honest work and I don't seek accolades or glory.\n\nI'm happy to try, but why would you seek me for this? There are plenty of smiths in the Undercity that will take on custom jobs like this.", sourceObjectiveStatus = "unverified-source-field" }
quests[95125] = { id = 95125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ott's Masterwork", description = "These are some truly fine materials, {class}. You honor me by allowing me to forge this blade for you and I only hope that I can live up to your expectations.\n\nPlease, stand back so that I may begin the forging process.", sourceObjective = "Watch as Ott forges your blade.", progress = "My blade will not fail you, {class}.", completion = "This blade is my finest work and I hope it serves you well in your travels. Thank you again for this opportunity.\n\nAka'Magosh, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[95126] = { id = 95126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moonsilver Blade", description = "Here's the blade. You said that a paladin named Trevan sent you? Please extend my thanks to him for this opportunity when you next see him. Go with honor, friend.", sourceObjective = "Bring Ott's Masterwork to Trevan Rol in Silverpine Forest.", progress = "Was Ott able to carry out the commission?", completion = "<Trevan takes the blade and inspects it carefully.> \n\nThis will do nicely, {name}. I knew that Ott had it in him to make something truly great.\n\nThe only thing left now is to kill that beast. Speak with Lumina when you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[95161] = { id = 95161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember That I Love You", description = "If you're looking for Jeremy Heartweaver, your best bet is to talk to his newly adopted mother, Avette Fellwood out in Duskwood. Sweet woman. Likely needs another pair of hands for her work, but it beats staying in the orphanage.\n\nIf you see little Jeremy do be sure to tell him we're all thinking of him, won't you?", sourceObjective = "Deliver the Blood-Stained Letter to Avette Fellwood in Duskwood.", progress = "Yes? What do you need?", completion = "Oh no...\n\nIt's nice of you to bring this, but I don't think Jeremy is ready to see it. Matron Nightingale said my little Jeremy hasn't spoken since the attack on Lordaeron, and I don't intend to force him now. Showing him this will only cause him more pain.\n\nDon't look at me like that. I won't hide his past from him, but he needs time to heal. I'll give this to him when he's older. Thank you for stopping by, but I think it's time you should go.", sourceObjectiveStatus = "unverified-source-field" }
quests[95189] = { id = 95189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest of Lordaeron", description = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in Stormwind would be very keen to get their hands on this.>", sourceObjective = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City.", progress = "Welcome to the gallery. Feel free to browse.", completion = "How in the world did you find this? It's in such remarkable condition... all things considered.\n\nThank you for restoring this piece of Alliance history, {class}. I'll have my best people get to work restoring this immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[95195] = { id = 95195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Insignia", description = "<The old Alliance insignia appears to have belonged to a soldier of Lordaeron. These ruins are likely filled with similar medals that living relatives would be grateful to have returned to them.>", sourceObjective = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City.", progress = "You look as if you're carrying a heavy burden, {name}. What is it?", completion = "Your instincts to bring these to me were not unfounded. When Lordaeron fell to the scourge, many people fled to take refuge here in Stormwind. There are likely few who remain to claim these insignias themselves.\n\nYour duty to Stormwind is commended, {name}. I'll begin distributing these tokens to next of kin right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[95204] = { id = 95204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest of Lordaeron", description = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in the Undercity would be very keen to get their hands on this.>", sourceObjective = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.", progress = "What have you got there, {class}? A tasty morsel?", completion = "<Oran bites the crest to ensure authenticity.>\n\nWell I'll be. A genuine relic of our home. Mostly intact, too. We need to be extra careful with this one.\n\nThank you for your aid in restoring our history, {class}. I'll see to it that we take good care of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[95212] = { id = 95212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Saddle on Quality", description = "We're getting ready to send a team of rams to reinforce the Alterac expedition, but we've run out of material to make their saddles.\n\nCollect pelts from the largest, fiercest leopards to the east and bring them to me. It's biting cold up there and our forces deserve nothing but the finest pelts to keep them warm!", sourceObjective = "Collect 6 Pristine Leopard Pelts and deliver them to Amberstill Ranch.", progress = "You look chilly, {class}. How goes the hunt?", completion = "These pelts will make excellent saddles. You've done the Alliance proud, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[95213] = { id = 95213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Blasting Powder", description = "The keg is stamped:\n\nBLASTING POWDER - DANGER - DO NOT HANDLE - DANGER - QUARRYMASTER AUTHORIZATION ONLY - DANGER\n\nYou get a sinking feeling that the troggs shouldn't have this. It would be best to report this to the quarry sooner rather than later.", sourceObjective = "Bring the Empty Powder Keg to Quarrymaster Thesten at Gol'Bolar Quarry.", progress = "What's that you've got?", completion = "<The {race} turns pale as he sees the empty keg.>\n\n...Where did you find this?", sourceObjectiveStatus = "unverified-source-field" }
quests[95214] = { id = 95214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Blasting Powder", description = "This keg held enough powder to turn King Magni's throne room into an open air courtyard. We've got to get it back from the troggs before they work out how to ignite it.", sourceObjective = "Recover 16 Stolen Blasting Powder from the troggs east of Gol'Bolar Quarry, then return to Quarrymaster Thesten.", progress = "I hope you've got good news for me?", completion = "That should be all the stolen powder. Thank you, {class}.\n\nPlease accept this reward, and... I'd appreciate if you didn't mention this little incident to anyone.", sourceObjectiveStatus = "unverified-source-field" }
quests[95216] = { id = 95216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Plague", description = "Welcome to the most vital organ of the Undercity: The Apothecarium! Here we experiment on the most virulent of Azeroth's exotic specimens.\n\nYou've caught me in a good mood, so I will let you in on my latest investigation. It appears there is a particularly venomous arthropod stalking the ruins above our fair city. Its toxins are said to eat through even undead flesh. How exhilarating!\n\nI wish to validate these claims. Should you find yourself withering away from its bite, I should love a sample.", sourceObjective = "Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity.", progress = "Any fool can tell you the most potent transmission method will always be through the blood.\n\nI must see this strain for myself!", completion = "You killed it??\n\nHmmph. Lucky for you this should be enough ichor to reverse engineer its properties. You do not wish to be an enemy of the Royal Apothecary Society.\n\nGet out of my sight!", sourceObjectiveStatus = "unverified-source-field" }
quests[95217] = { id = 95217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quarry's Smith", description = "So you're looking to learn the blacksmith's trade? Maybe we can help each other.\n\nThe supply shipment's late, and I need materials for some repairs around the camp. If you get me what I need, I'll teach you some of my techniques. Sound fair?", sourceObjective = "Collect 12 Copper Bars and 4 Toughened Boar Hides and deliver them to Frast Dokner.", progress = "Don't slack off, {name}. Smithin' isn't for the lazy!", completion = "You're a resourceful one, {name}.\n\nNow listen up - I'm not going to repeat myself!", sourceObjectiveStatus = "unverified-source-field" }
quests[95250] = { id = 95250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abominable Creatures", description = "What do you want, {race}? Can't you see there is a war to be won?\n\nMy master has already charged into the fray and has ordered me to maintain my post. It has been quite some time, however.\n\nI doubt you'll survive ten minutes in combat, but if it keeps your simple mind busy, why don't you seek out the Grand Marshal. He is the tallest, most statuesque hero you've ever laid eyes on. You'll know him when you see him.You will be able to choose one of these rewards:", sourceObjective = "Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman.", sourceObjectiveStatus = "unverified-source-field" }
quests[95314] = { id = 95314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Shadowvale Green Elixir", description = "Before the Scourge invasion, the reclusive village of Shadowvale was known for its Whispering Elixir. Distilled from herbs found only in Tyr's Fall, the elixir was sought by apothecaries, mystics, and poisoners alike even after being banned in the city.\n\nI've had requests from a number of buyers eager to get their hands on some elixir. Travel to the ruins of Shadowvale deep in the Whispering Forest to the west. I'm prepared to offer significant compensation if you can recover some bottles for me.", sourceObjective = "Collect 8 Bottles of Whispering Elixir from Shadowvale, then return to Carolai Anise in Brill.", progress = "I trust you did not get lost?", completion = "You say there is evil in Shadowvale? I admit, I am not surprised. The forest folk were an odd lot, and they did not care for visitors. Some believe the Whispering Forest itself is cursed, and the elixir distilled from its roots carries that same curse...\n\n...but enough of superstition and rumors, {name}. Thank you for the elixirs. Here, take this as payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[95328] = { id = 95328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispering Horror Residue", description = "Against your better judgement you scrape up and collect the squirming remains of the beast. Someone in Undercity might have a use for them.", sourceObjective = "Deliver Whispering Horror Residue to Father Lankester in the War Quarter of Undercity.", progress = "Do you have something for me, {class}?", completion = "What an interesting specimen. From underneath the Whispering Forest, you say? It's no secret that foul place is touched by the void.\n\nI welcome the opportunity to explore the mysteries of shadow, {class}. Allow me to offer you payment for what you've found.", sourceObjectiveStatus = "unverified-source-field" }
quests[95349] = { id = 95349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen Ring", description = "The recent events with the cult have delayed my plans to travel to Azeroth and I must remain here in Valanaar for a time. You and a handful of other Windshapers will be our vanguard instead. Alaana Stormwalker will be waiting to receive our Windshapers upon arrival in Mulgore, and I'd encourage you to explore Azeroth while we finish our business here. We will join you soon.\n\nWhen you are ready, please proceed to the dock just outside this lodge and board the skycutter ship there. \n\nBanu-Alah, {name}.", sourceObjective = "Take the skycutter ship from Zephras Isle to Mulgore and speak with Alana Stormwalker when you arrive.", completion = "More adventurers from Zephras, I see. Wonderful. The winds surely favor us! It's going to take us some time to get ourselves established here, so you may want to take some time to explore this new land.\n\nAzeroth is an exciting new world, but it's also a dangerous world. You'd do well to prepare yourself for this new adventure by familiarizing yourself with the lands nearby.", sourceObjectiveStatus = "unverified-source-field" }
quests[95350] = { id = 95350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Azeroth", description = "Its a big world down here, and our new allies are the key to our survival.\n\nThe Earthen Ring is a member of the \"Horde\", a proud collection of like-minded peoples. The nearby city of Thunder Bluff is a part of the horde, and further to the east lies the capital of Orgrimmar.\n\nSeek out the flight master in the center of Thunder Bluff. They will fly you to Orgrimmar where you will make contact with the horde warchief--Thrall, on behalf of the Windshapers. Winds guide you, {name}.", sourceObjective = "Travel to Orgrimmar and speak with Thrall in the Valley of Wisdom.", completion = "Lok-tar, {class}. I am Thrall, Warchief of the Horde.\n\nAn Earthen Ring messenger told me to expect members of the Windshapers, and here you are. I'd not have expected to see a high elf standing before me here in Orgrimmar, but the horde will welcome you as our guest all the same.\n\nYou have my blessing to travel through horde lands. Go with honor, Windshaper.", sourceObjectiveStatus = "unverified-source-field" }
quests[95494] = { id = 95494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruised Pride and Lion Hides", description = "I need someone with a strong sword arm and some extra time on their hands to help me gather some lion hides. It stings my pride to ask a stranger for this aid, but I took an injury to my leg recently. Until I heal, I'm in no shape to go hunting myself but I have obligations to keep.\n\nThe big ones in this area generally have the best hides, so start with those first.", sourceObjective = "Collect 6 Savannah Lion Hides from the Savannah Matriarchs and Savannah Patriarchs in the Barrens.", progress = "How goes the hunt?", completion = "Yes, these look like they will do nicely. I have an arrangement with a local tanner to deliver these raw hides in exchange for various finished leather goods that I use as part of my trade. \n\nI've never come up short on my end of the arrangement, and even with my injury I do not intend to start now.", sourceObjectiveStatus = "unverified-source-field" }
quests[95495] = { id = 95495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit Tanner", description = "These hides are bound for a tanner who I often trade with. He is something of a hermit and he lives alone on the top of the ridge behind me. Climbing up a steep hillside isn't something I can manage easily right now so I'd be in your debt if you could make this delivery for me.\n\nOh, and about this tanner's... appearance. You need not be alarmed. In spite of his looks, he is no threat. I swear this is true.", sourceObjective = "Bring the Bundle of Hides to the hermit on the ridge overlooking the Dry Hills in the Barrens.", progress = "Greetings, {class}. What brings you up to my property today?", completion = "Vrang sent you then? Very well. I appreciate you delivering these hides to me. It's unfortunate that Vrang couldn't make the journey himself. There is a matter I wish to speak with him about.", sourceObjectiveStatus = "unverified-source-field" }
quests[95507] = { id = 95507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrang's Game", description = "While you are out there, it would be of great help to me if you could check on my traps for me. I've got them strewn all over the valley.\n\nBring back any small game that I've caught. Keep your eye out for the other wildlife, though. This area can be dangerous if you aren't paying attention.", sourceObjective = "Collect 8 Trapped Game from traps found in Sprung Traps in the Barrens.", progress = "<Vrang grunts at you as you approach.>", completion = "Thank you for your aid, {class}. I was starting to wonder if I'd have to go to bed hungry tonight because this cursed wound on my leg.", sourceObjectiveStatus = "unverified-source-field" }
quests[95508] = { id = 95508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Guests", description = "Yes, I used to be a member of the Kul Tiras navy. After Lord Admiral took Theramore and started his campaign in Durotar, I had... \"objections\" to his methods. Particularly the methods involving executing civilians.\n\nThere's more to the story but... wait... what's that?\n\nThere's a group of men coming up the ridge!", sourceObjective = "Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines.", completion = "Well, looks like we are all alive. I... knew that someday that would catch up to me. I'm in your debt for your help here today.\n\nPlease, take this. It's not much, but its the least I can do.\n\nSafe travels, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95534] = { id = 95534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahnbrad Mystery", description = "<The note is singed in places, but is still readable.>\n\nRumor has it those old bellows have a mind of their own, springing to life when no one is watching. I don't care if it's a ghost story, you'd better get to the bottom of it before I return.\n\nThere's great power in Strahnbrad, I know it.\n\n< The rest of the note is singed and torn, as if burnt by fire magic. >", sourceObjective = "Solve the mystery of Strahnbrad and report your findings in town in Hillsbrad.", sourceObjectiveStatus = "unverified-source-field" }
quests[95621] = { id = 95621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Valley", description = "This morning I spotted a group of humans searching for something in the valley below. I managed to use my rifle's scope for a better look, and it was clear that they were soldiers sporting the livery of Kul Tiras. \n\nIf you'd be willing to take work from me, travel to where these soldiers made camp near the wrecked caravan to the south. Kill any you find and try to learn why they are here.", sourceObjective = "Travel to the wrecked caravan and learn more about why the Kul Tirans are here.", progress = "The remnants of Daelin Proudmoore's fleet who still fly his banner are just as rotten and barbaric as the admiral himself was before he died.\n\nI don't know why they are so far from Tiragarde, but it can't be good.", completion = "So they are looking for a deserter... Well, it seems that the past has finally caught up to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[95646] = { id = 95646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horrors in the Highland", description = "These brackish wetlands hold a greater well of unsalted southern waters. It pains me, yet within my roots I sense a corruption seeping through that mountain gully.\n\nThe creatures, like those in our lowlands, react more bitterly to the taint. Lacking the sea's hardening salt since life's dawn, they have little strength against such evil.\n\nGo to those highlands, and bring me the Highland Horror's root core.You will be able to choose one of these rewards:", sourceObjective = "Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[95647] = { id = 95647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Thicket Things", description = "My husband, Ardin, has a rare gift for sensing nature. He'll scale any peak to gather the herbs and flowers I need for my alchemy, keeping our shelves and pantry stocked.\n\nBut I fear he's wandered into trouble. An excavation crew passed through seeking supplies. They spoke, among other things, of towering grasses unlike anything they'd ever seen. Those were what he told me he had to go see for himself. He's been gone too long!\n\nIf you learn anything of him, I'd be grateful.", sourceObjective = "Find Ardin Grassman in the Excavation Sites.", sourceObjectiveStatus = "unverified-source-field" }
quests[95663] = { id = 95663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Rumors", description = "The Dragonmaw are a formidable clan.\n\nThey're known for binding magic strong enough to make dragons serve, and rumor claims they're preparing some display of it in the Wetlands. Whether truth or bluster, the Deathstalkers can't act on half-formed whispers. Titanic winds carried only that much to me.\n\nA deathstalker agent needs a hand in the hills above the Dragonmaw encampment. Meet her there. She'll reveal the next steps.", sourceObjective = "Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[95664] = { id = 95664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Knowledge", description = "This unusual composite shard scatters light like a living prism. Its nature is uncertain, but its power feels ancient. The most knowledgeable minds for artifacts of this bygone age must reside on the Elder rise in Thunder Bluff.", sourceObjective = "Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[95682] = { id = 95682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open the Maw", description = "Dragonmaw. <She lets out a dry, amused scoff.>\n\nThe remnants of the dragon-wrangling clan think they've found something that could lead to them rising to their former power. In the eyes of whom... their false warchief?\n\nClear out their ragtag clan within the Excavation Sites so our Deathstalkers can move in undetected.\n\nIf the Dragonmaw carry anything of note upon them, return it to me--this information must stay between us and our royal command.You will be able to choose one of these rewards:", sourceObjective = "Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover.", sourceObjectiveStatus = "unverified-source-field" }
quests[95697] = { id = 95697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing Tastes", description = "Zamja tells me we need more homestyle cooking.\nIf we start selling raptor, she thinks it'll draw in customers who don't usually visit Borstan's Firepit.\n\nHer idea is not so bad. But I want something that rises above the smells of our birth villages. We're in Orgrimmar! Borstan should serve a grand take on their familiar favorites.\n\nA hunter recently came back from the Wetlands with a giant talon from the thicket raptors in the Excavation Sites.\n\nUp for a job?You will be able to choose one of these rewards:", sourceObjective = "Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat.", sourceObjectiveStatus = "unverified-source-field" }
quests[95737] = { id = 95737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Caitlin", description = "From time to time, I correspond with others in my craft--herbalists or eccentrics who study rare plants and local oddities. We trade discoveries, and sometimes warnings of what lies ahead.\n\nOne alchemist in the Wetlands wrote of an excavation team her husband was part of, uncovering signs of a long-lost primordial grass... but she never sent word of its abundance or accessibility.\n\nIf you can, check on Caitlin Grassman in Menethil Harbor.", sourceObjective = "Speak with Caitlin Grassman in Menethil Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[95748] = { id = 95748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gurubashi Legends of Old", description = "This is odd. This piece of the tablet you have brought me refers to the lost city of I'lalai as if it is a massive sprawling civilization. But the ruins off of the reef are not large enough to be something of that size.\n\n{name}, to the north of the Vile Reef there is an ancient troll ruin on the hills along the coast. A tablet that contains legends of the lost troll city is within. I wish to study this legend further.\n\nTake this hide and charcoal to create a rubbing of this tablet, then return to me.", sourceObjective = "Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet.", sourceObjectiveStatus = "unverified-source-field" }
quests[95771] = { id = 95771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Darkness" }
quests[95772] = { id = 95772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Songblade Search", description = "Me brother tried draggin' me off tae the Wetlands with some diggin' crew out o' Loch Modan. Said they were headin' into hills no dwarf's ever set boot in for some sort o' excavation.\n\nAye, I'd 'ave gone, if I wasn't already behind on this pile o' girdles I've got to refit.\n\nDaewyn normally writes after he sends off, though. Haven't heard a thing, gives me a strange feelin' this time.\n\nIf yer marchin' that way, mind checking in on me brother?", sourceObjective = "Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site.", sourceObjectiveStatus = "unverified-source-field" }
quests[95774] = { id = 95774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Name Is Olgra", description = "The healer who saved me could not save her, and she has died in battle. Her name is Olgra, and I will never forget her.\n\nYou did not find her adornments on her body? She wore many jewels of polished bone.\n\nSlay the Razormane Raiders near where she fell, and find her precious works of art!\n\nI will place them with the memorial that I build in her memory.", sourceObjective = "Slay quilboars and collect 4 of Olgra's Adornments for Mankrik's memorial.", progress = "I have only memories now, but I will build a tribute to Olgra so that they never fade.", completion = "I will place these adornments with my wife's memorial, so that I never forget her. My blood will always run hot with revenge!\n\nYou have done me... done us... a great favor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[95795] = { id = 95795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen in the Fen", description = "<You cover the dwarf's body with his cloak.>\n\nTravel to Lakeshire and personally inform Dorin Songblade what became of his brother within the Excavation Sites.", sourceObjective = "Return to Dorin Songblade.", completion = "Ah no...\n<He buries his head in his hands and sobs.>\n\nI should 'ave gone with 'em. \n\nMuch of what I was smithin' was for 'im, was plannin' a surprise but it wasn't ready when he came by gettin' things for his journey.\n\nNow that these are finished, I don't have it in me to reforge or sell any of it.\nYou can have this. It's the least I can do for you, bringing me this grim day.", sourceObjectiveStatus = "unverified-source-field" }
quests[95803] = { id = 95803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Good Faith", description = "Now that we've claimed the head of the tarnished commander, I need you to deliver it to the Undercity. Sylvanas Windrunner mistrusts us greatly, and all but openly disparages us.\n\nDeliver Rudolph Gelhardt's head to the Dark Lady. Show her that we tend to our own house and are devoted to the prosperity of the forsaken.", sourceObjective = "Bring the head of Rudolph Gelhardt to Sylvanas Windrunner in the Undercity.", progress = "Why are you addressing me, {class}?", completion = "I don't doubt Danitha's sincerity and desire to earn a place for your kind amongst the Forsaken. However, I suspect that this isn't the last time we'll see one of your brothers and sisters go mad and turn the light against their own people.\n\nThere may come a time when I decide that tolerating your misbegotten order is no longer in the best interests of the Forsaken. I suggest you continue to serve your people diligently.\n\nWe will be watching.", sourceObjectiveStatus = "unverified-source-field" }
quests[95805] = { id = 95805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grace of An'she and Mu'sha", description = "The sun and the moon, An'she and Mu'sha, are not part of our world like the elements, yet their light gives us life, guidance, and hope.\n\nWe pay respect to the spirits of the world, and so we pay respect to the twins as well.\n\nIf you would show your respect, take this smoldering incense and bring it to a shrine in the hills to the southeast, overlooking the mesa, south of the quilboar. Be quick, so that you can reach the shrine before the incense burns away.\n\nDon't get it wet!", sourceObjective = "Carry the Smoldering Incense to the shrine of An'she and Mu'sha in the southeastern hills before the incense burns to ash in ten minutes!", progress = "<The smoke from the incense rises toward the sky.>", completion = "<As you empty the incense into the fire, the scent wafts around you, leaving you with just the empty pouch and a subtle sense of fulfillment.>", sourceObjectiveStatus = "unverified-source-field" }
quests[95809] = { id = 95809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartwoven", description = "I need a moment to rest before I find my own way out.\n\n<He pulls some reeds from his pack and quickly braids and bends them into a heart.>\n\nTake this, and bring it back to Caitlin. Let her know I'll be home soon! Now that we have a path cleared out thanks to you, I'll gather my bushels and follow your trail.\n\nThank you.", sourceObjective = "Return to Caitlin Grassman in Menethil Harbor.", progress = "I'm more than worried about him!", completion = "Goodness, that sounds terrible!\n\nBy the light, I'm grateful he's one of the survivors.\n\n<She holds the reed-woven heart to her own.>\n\nI'll start cooking a hearty meal for him. Thank you for bringing me this. I'd like you to have something as a token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[95810] = { id = 95810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Relic Carry", description = "You pick up a fractured piece of the rock-mech automaton. It has a texture unlike anything you've touched before, a composite material of unknown makeup. This is certainly bound to be more 'device' than 'debris.'\n\nProspector Whelgar himself at his excavation site might have something useful to share about the relic.", sourceObjective = "Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site.", sourceObjectiveStatus = "unverified-source-field" }
quests[95816] = { id = 95816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sign Me Up!", description = "Greetings, accomplished craftsperson!\n\nCompletion of this form will grant you non-exclusive, revocable, and legally limited permission to display advertisement signs for your tradeskill(s) all across Azeroth!\n\nOnce completed, please bring this to your local Azeroth Commerce Authority branch's Contract Coordinator to begin processing.\n\nHappy crafting!", sourceObjective = "Bring the completed form to Elaine Compton in Redridge Mountains.", sourceObjectiveStatus = "unverified-source-field" }
quests[95819] = { id = 95819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sign Me Up!", description = "Greetings, accomplished craftsperson!\n\nCompletion of this form will grant you non-exclusive, revocable, and legally limited permission to display advertisement signs for your tradeskill(s) all across Azeroth!\n\nOnce completed, please bring this to your local Durotar Supply & Logistics Contract Coordinator to begin processing.\n\nHappy crafting!", sourceObjective = "Bring the completed form to Jornah in The Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[95883] = { id = 95883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tortured Soul", description = "<The preparations for a hastily-assembled ritual are gathered unceremoniously on the altar. According to the scrap of note, everything has been gathered. All that's missing are the offering of blood and the Tortured Soul.\n\nThe undead around you look tortured enough. They may have what you seek.>", sourceObjective = "Collect a Tortured Soul from the nearby undead in Beren's Peril in Silverpine Forest.", progress = "<The offering stone is ominously still.>", completion = "<The tortured soul lets out a foul energy in the presence of the offering stone.\n\nIt appears you are closer to fulfilling the ritual.>", sourceObjectiveStatus = "unverified-source-field" }
quests[95884] = { id = 95884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offering Stone", description = "<The scrap of note is mostly illegible. What is still readable, however, are notes about preparations for an offering.\n\nAn offering stone is mentioned, as well as a ritual.\n\nPerhaps you can find this offering stone nearby.>", sourceObjective = "Find the Offering Stone in Beren's Peril in Silverpine Forest.", completion = "<Strange implements and items litter the rough surface of the stone.\n\nThis is surely the offering stone that is mentioned in the note.>", sourceObjectiveStatus = "unverified-source-field" }
quests[95885] = { id = 95885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offering of Blood", description = "<All that's left now is the offering of blood.\n\nThe note scrap mentioned a 'willing sacrifice.'\n\nAn intense sense of dread washes over you.>", sourceObjective = "Use the Tortured Soul to give an offering of blood at the Offering Stone in Beren's Peril.", progress = "<The offering stone is ominously still.>", completion = "<The offering stone is inert now. It appears your ritual drained it of power. To what end, you do not know, but it is over now.\n\nThe rough stone cracks and crumbles, now devoid of purpose.\n\nSomething glitters from within the remnants...>", sourceObjectiveStatus = "unverified-source-field" }
quests[95981] = { id = 95981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watching the Roads", description = "Taking away their pendants is just the first step. If the Kirin Tor really are shipping a steady supply of relics from Dalaran, we must stop them at the source.\n\nSearch the roads around Ambermill for Dalaran's wizards and watchers. Their presence has allowed free access across our borders for too long. If we can cull their numbers, that should put a stop to these pendants making it into Silverpine Forest in the first place.", sourceObjective = "Slay 8 Dalaran Wizards and 8 Dalaran Watchers for Shadow Priest Allister in the Sepulcher.", completion = "Ever since the barrier went down around Dalaran, the Kirin Tor have maintained a death grip on the roads. They're paranoid about something, that much is certain.\n\nFor now, however, the why is irrelevant.", sourceObjectiveStatus = "unverified-source-field" }
quests[95998] = { id = 95998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Well howdy there, {class}. I can see you've got the look of an adventurer about you. Good for you. The world needs more of us restless souls, seeking fortune and glory.\n\nIt's a big wide world out there and you'll need to learn to thrive in the wilds to be successful. Not sure how your outdoorsman skills are but I reckon I could teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire, get comfy. I'll walk you through it.", sourceObjective = "Sit near Sam's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill. They will also teach you the know-how to create a proper camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[95999] = { id = 95999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Incinerator Gar'im", description = "Wanted! Incinerator Gar'im, Leader of an orc incursion in Render's Valley. Purported to be working with the Blackrock of Stonewatch Keep.\n\nBeware of Incinerator Gar'im. He and his Shadowcasters are extremely dangerous. A handsome reward will to be given to any brave soul that can deliver proof of Incinerator Gar'im's demise to Magistrate Solomon.", sourceObjective = "Deliver the Broken Staff of Incinerator Gar'im to Magistrate Solomon in Lakeshire.", progress = "What do you have there, {race}?", completion = "Excellent work, {name}! Incinerator Gar'im was preparing to bolster the defenses at Stonewatch Keep. With this victory, we may yet succeed in reclaiming the keep!", sourceObjectiveStatus = "unverified-source-field" }
quests[96016] = { id = 96016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempest's Weapons", description = "Ye did good, and I can see yer itchin' fer yer reward. Sorry tae say, I'm not exactly a dwarf of many possessions.\n\n<Veyric gestures broadly at his remote location.>\n\nTell ye what, though. I hear a troll named the Windwatcher lives out in the Alterac Mountains. He's a powerful shaman himself, and an expert in storm elementals. If ye bring that there elemental core to him, I bet he can make ye a weapon worthy of yer victory.You will be able to choose one of these rewards:", sourceObjective = "Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", sourceObjectiveStatus = "unverified-source-field" }
quests[96031] = { id = 96031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Leatherworking", description = "You've become a leatherworker. Good for you, {class}. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels.", sourceObjective = "Speak with Gretta Finespindle in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, your very own camp tent. Most folk don't care much for tents being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96044] = { id = 96044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", sourceObjective = "Speak with Tognus Flintfire in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96045] = { id = 96045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Alchemy", description = "Now that you've taken up Alchemy, I can also teach you how to craft a Mana Well for your camp once you've learned a bit. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", sourceObjective = "Speak with Vosur Brakthel in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Mana Well. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96046] = { id = 96046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Mining", description = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.", sourceObjective = "Speak with Yarr Hammerstone in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can now craft your very own Lodestone. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96047] = { id = 96047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: First Aid", description = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a {class}.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.", sourceObjective = "Speak with Thamner Pol in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "I can teach you once you've gained some skill with your profession.", completion = "There you have it, you can now craft your very own First Aid Kit. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96050] = { id = 96050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Fishing", description = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.", sourceObjective = "Speak with Paxton Ganter near Iceflow Lake in Dun Morogh to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Fish Bowl. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96055] = { id = 96055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Herbalism", description = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate.", sourceObjective = "Speak with Reyna Stonebranch in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Incense Candle. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96056] = { id = 96056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Skinning", description = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.", sourceObjective = "Speak with Balthus Stoneflayer in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Camp Chair. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96057] = { id = 96057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Tailoring", description = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized.", sourceObjective = "Speak with Uthrar Threx in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Rallying Banner. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96058] = { id = 96058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Engineering", description = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells.", sourceObjective = "Speak with Bronk Guzzlegear in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Reagent Bot. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96059] = { id = 96059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Enchanting", description = "Now that you've begun your journey into being an enchanter, I reckon I can teach you how to craft an Enchanted Lute for your camp once you've learned the ropes.\n\nIt's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.", sourceObjective = "Speak with Thonys Pillarstone in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", progress = "Yes, I can teach you.", completion = "There you have it, you can now craft your very own Enchanted Lute. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96101] = { id = 96101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Raan's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96102] = { id = 96102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Tailoring", description = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized.", sourceObjective = "Speak with Snang in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Rallying Banner. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[96130] = { id = 96130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chakuyak", description = "Among the prairie wolves that hunt the hills nearby is one that is especially aggressive. We have taken to calling her Chakuyak. She has become a threat to travelers coming from abroad.\n\nShe stalks the trees west of Stonebull Lake, moving from tree stand to tree stand.\n\nEnd this threat and bring me her pelt, and I will speak your praises to the chief. Beware, for she is dangerous! You might see other hunters seeking her out there, and perhaps you could work as a team.", sourceObjective = "Defeat Chakuyak and bring back her pelt.", progress = "Have you found the big wolf?", completion = "Taking the life of such a beautiful creature is a sad event, but it was necessary for the safety of our people. I will make certain that the pelt does not go to waste. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96135] = { id = 96135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heed My Call", description = "Euck, just bein' around these blasted totems is givin' me the willies--but that's good. This much twisted corruption will be exactly what we need tae summon the quilboar's elementals.\n\nGo to the Thousand Needles and find a suitable spot for your defenses. The steam pools should work. They're rich with fire, earth, water, and air alike. Place these totems and be ready for a fight. The Razormane won't take too kindly to yer interference.", sourceObjective = "Use the Twisted Totems to put an end to the quilboar ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[96136] = { id = 96136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "As you have no doubt experienced yourself, the elements of Azeroth are unique to those in Zephras. It is one thing to channel the forces of nature within the elemental plains, and another thing entirely to do it down here in the muck.\n\nI could grant you your totem of air, but I think it would do you more good to meet with the one who trains the other earth-bound initiates. What say you, {name}?", sourceObjective = "Find Prate Cloudseer in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[96137] = { id = 96137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ira's Dagger", description = "A small dagger belonging to the self-appointed ranger, Ira, who kept the forests safe by preventing the beasts within from attacking travelers.\n\nWith Ira's spirit still wandering the woods, perhaps her unfinished business was to clear out the worg that continue to claim victims throughout the forest.", sourceObjective = "Defeat 10 Young Black Ravagers and 7 Black Ravagers then return to Sirra Von'Indi in Darkshire for more information.", progress = "What have you got there?", completion = "Ira? Are you sure? Sounds like the woman was damn near a ghost before she died. I'm surprised you found her.\n\nRest assured I will take great care of this dagger.", sourceObjectiveStatus = "unverified-source-field" }
quests[96138] = { id = 96138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merrick's Bow", description = "A bow left by the spirit of Merrick Valor, famed Watcher who prided himself on keeping the roads safe from encroaching enemies.\n\nWith Merrick's spirit still wandering the roads, perhaps his unfinished business was to clear out invaders near his home in Raven Hill. The ogres south of town may be what's troubling his spirit.", sourceObjective = "Defeat 8 Splint Fist Warriors and 4 Splint Fist Taskmasters then return to Sirra Von'Indi in Darkshire for more information.", sourceObjectiveStatus = "unverified-source-field" }
quests[96139] = { id = 96139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valor Family", description = "In dark times like these, it's important we remember our heroes as much as our foes. Darkshire would not still be standing if it weren't for the bravery of folk like the good Lady Althea or those who lost their lives at Raven Hill.\n\nHave you read much on Raven Hill? No, of course not. Its history was wiped out along with its people. My library, impressive as it is, has little on the subject.\n\nIf you happen to find anything, I would appreciate bringing it here. Those folk deserve to be remembered.", sourceObjective = "Search Raven Hill for anything of interest and return to Sirra Von'Indi in Darkshire.", progress = "Have you found anything? I'm not holding out much hope.", completion = "This tome appears to be about the Valor family. I believe I've heard of a few of them. Good folk. Not sure they merit an entire book about them.\n\nI'll make you a copy of the tome. If you see anything else related to them on your travels, I'll be happy to take it off your hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[96204] = { id = 96204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windshaper's Wrath", description = "Now that I'm free I'm going to make these vile creatures regret ever laying eyes on a Windshaper.\n\nLet's get out of here, {class}.", sourceObjective = "Accompany Lumina Windsinger and help her escape Fenris Keep.", completion = "Thank you again, {name}. I've been aquatinting myself with Trevan here, who I've learned sent you along on my trail.\n\nI've heard... less than charitable things about paladins thus far in my travels. As a sky-touched shen'dorei elf traveling through horde territory, I can certainly understand how easily intolerance and prejudice can take root. \n\nYou and your kind have a friend among the Windshapers.", sourceObjectiveStatus = "unverified-source-field" }
quests[96222] = { id = 96222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "While war rages throughout the region, the Maraudine centaur stand unchallenged in the Valley of Spears. I worry that they will grow callous in time and stir further unrest if the other clans continue to turn a blind eye to their presence.\n\nKhan Hratha possesses a Maraudine Key Fragment, and I wish to have it as a negotiation tactic. Find a war horn mouthpiece from the centaur there and use it to challenge him atop the highest peak.\n\nBring the key to me, and I will have a proposition for you.You will be able to choose one of these rewards:", sourceObjective = "Bring the Maraudine Key Fragment to Umarak in the Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[96241] = { id = 96241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talkin' bout Toxins, Mon", description = "Something funny be happenin' over there at Gloomrise. Ol' Mazu'kon be hearin all about these nasty new beasties skitterin' all around there.\n\nSome say those creepy crawlies got a venom that have some unique properties and this be gettin' me curious. Take my extractor. Use it on the dead bodies layin' around that place to harvest the venom. Do this and I be in ya debt, mon.", sourceObjective = "Use the Toxin Extractor to gather 5 Gloomrise Toxin Samples from the Gnawed Corpses at Gloomrise.", sourceObjectiveStatus = "unverified-source-field" }
quests[96243] = { id = 96243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "It's past time ye heeded the earth, brave Shaman. The elements already prickle in yer skin, but once ye speak with the stone, the ground itself'll set firm 'neath yer soles--and in yer soul.\n\nSeek out Teo Hammerstorm, in Coldridge Valley. Ye'll find him within Anvilmar, a holdfast forged by hammer, fire, and will.", sourceObjective = "Find Teo Hammerstorm in Dun Morogh.", completion = "The land itself let me know ye were comin'! Aye, sometimes, the burnin' fire within us is enough to power us through the snow without even touchin' the ground!", sourceObjectiveStatus = "unverified-source-field" }
quests[96259] = { id = 96259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Dead", description = "There is an ancient tauren burial ground at the place called Gloomrise, just northwest of this camp. Of late it has been infested with a particularly vicious brood of spiders. These spiders not only pose a threat to the people of Mulgore, they are also damaging a site that most tauren consider to be sacred.\n\nIt would be of great service if you could travel to Gloomrise and put an end to this infestation. The ancestors will surely smile upon you if you see this done.", sourceObjective = "Kill 10 Gloomrise Hatchlings and 5 Gloomrise Soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[96260] = { id = 96260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stronger than Steel", description = "Have you heard what befell the burial ground at Gloomrise? Giant spiders--rumored to have a venom so strong that it can wake the dead--have spread like wildfire. Nasty business, if you ask me.\n\nOne of the scouts dispatched to investigate returned half dead and covered in an incredibly resilient, crystalline spider silk. I harvested what I could, but I would highly value more samples of this silk for additional study.\n\nBring me more of this crystalline silk and I will reward you.You will be able to choose one of these rewards:", sourceObjective = "Gather 3 strands of Crystalline Silk from Gloomrise Spinners.", sourceObjectiveStatus = "unverified-source-field" }
quests[96261] = { id = 96261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broodmother", description = "As is often the case with infestations such as the one we are facing at Gloomrise, a single powerful matriarch often leads to the rapid spread of a hostile spider population.\n\nIf we wish to drive these beasts off for good, we'll need to seek out the progenitor and end her. When you go to Gloomrise, seek out the broodmother there and destroy her. I'd advise you to bring allies, and be ready for anything. These seem to be no ordinary spiders.", sourceObjective = "Kill Broodmother Valraxx at Gloomrise.", sourceObjectiveStatus = "unverified-source-field" }
quests[96264] = { id = 96264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Aid", description = "So yer a big shot shaman now, eh? Ye've mastered the elements and want tae put 'em to good use? I think I got just the thing.\n\nIf ye want the elements' respect, ye gotta repay yer debts to 'em. They help you, you help them. And right now they need all the help they can get from those who would abuse their power.\n\nEarth's rumblin', {name}. It speaks of the quilboar amassin' for some ritual of terrible power. We need tae go investigate their kraul and see what they're up to. Bring me back whatever ye find.", sourceObjective = "Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[96294] = { id = 96294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Darker Truth", description = "<The Broodmother you just killed is no spider at all, but rather a night elf druid who assumed a twisted animal form. A variety of questions flood your mind about the nature--and purpose--of the spiders at Gloomrise.\n\nYou notice a note peeking out of the folds of the dead elf's robe. Perhaps this document may answer some of the questions filling your head.>", sourceObjective = "Bring the letter you recovered from Broodmother Valraxx to Muln Earthfury at Skywatcher Plateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[96390] = { id = 96390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nip 'Em in the Bud", description = "Dark Iron spies have infiltrated Dun Morogh. To what end I canna' not sure, but this is a problem we need to nip in the bud before it is allowed to grow.\n\nHead eastward to Ironband's Compound and kill the Dark Iron spies that you find there.", sourceObjective = "Slay 10 Dark Iron Spies in Dun Morogh.", completion = "These Dark Irons may be our cousins but they ain't family, that's for sure. I shed no tears for any misfortune that befalls them that stray too far from that accursed mountain o' theirs.\n\nHopefully this is enough to put 'em off of further incursions into these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[96391] = { id = 96391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Map", description = "<The map you are holding seems to show a complex series of underground tunnels and highways that all seem to converge on a point underneath Ironforge itself.\n\nYou can't be sure what the runes say as they are written in the ugly jagged rune language of the Dark Iron dwarves, but you can guess at the purpose of these tunnels. As you are reading the map, a gust of wind washes over you and you can faintly hear a dwarven voice carried on it. Earthseer Farsen needs to see this.>", sourceObjective = "Deliver the Dark Iron Map to Earthseer Farsen in Dun Morogh.", progress = "Oh what's this, then?", completion = "Judging by this map, it certainly looks like these Dark Irons are planning some sort of incursion into the vaults beneath Ironforge. The band ye busted up to the east must be a scouting force.\n\nThank ye for bringing me this. If we hurry, we might be able to beat them to whatever their goal is down there.", sourceObjectiveStatus = "unverified-source-field" }
quests[96392] = { id = 96392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farsen's Watch", description = "Greetings to ye, friend. My name is Earthseer Farsen and I'm visiting Dun Morogh from Aerie Peak. As I was travelin', I couldn't help but notice that we have, well... a bit o' a Dark Iron Dwarf problem.\n\nIf ye have a moment, I can show ye what I mean. I've got a bit o' magic that should do the trick.", sourceObjective = "Speak with Earthseer Farsen's and ask him to lend you his farsight to observe the Dark Iron threat.", progress = "Farsight can show ye a great many things, even things ye'd rather not see.", completion = "So ye see now, {class}? Thick as cockroaches they are, and that's just the ones we can see from the sky.\n\nYe look like a sturdy enough sort. Hows about a bit o' violence?", sourceObjectiveStatus = "unverified-source-field" }
quests[96394] = { id = 96394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Dead", description = "Something has disturbed the tombs down in the Hall of Thanes, and strange noises have been heard coming from deep within the vaults. The spirits of the dead are light sleepers, and whatever is going on down there seems to have startled them.\n\nHead down there and see what you can do about that for us. If any of the dead are awake--well, put them back down!", sourceObjective = "Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest.", progress = "I don't have time for ghouls and ghosts. I have a job to do down here.", completion = "Ah good, its done then. I can't have the other keepers refusing to enter the hall to do their duties on account of \"ghosts\" and \"angry dead\", can I?", sourceObjectiveStatus = "unverified-source-field" }
quests[96395] = { id = 96395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Grudge", description = "The... Thane... my mighty... Thane... he... needs to... rest.\n\nPlease... help him... help him... rest...\n\nConsumed... by... ancient... grudge... No... rest...You will be able to choose one of these rewards:", sourceObjective = "Put the spirit of Faldrim Anvilmar to rest and then return to the Ghostly Attendant in the Hall of Thanes.", sourceObjectiveStatus = "unverified-source-field" }
quests[96403] = { id = 96403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Important Heirlooms", description = "You there, adventurer... I could really use your aid.\n\nI was sneaking--uh... 'patrolling' in the vaults when a force of Dark Iron dwarves emerged from the depths in mole machines! I don't know what they are here for, but there is priceless loot--uh or, rather... I mean, 'important cultural heirlooms' down there! Please, recover any such relics you see and return them here.\n\nI assure you that anything you recover will be catalogued and returned to its proper place of honor.", sourceObjective = "Collect 8 Dwarven Heirlooms from the Hall of Thanes.", progress = "<Thom appears to absentmindedly rub his hands together as he looks at you.>", completion = "Look at you, as brave as you are enterprising! I'm a gnome of my word, and your reward is well earned! \n\nNow, let me take a look at the haul--uh, I mean... the recovered heirlooms. I need to get started appraising--excuse me, 'cataloging' them so that they can be put back in their proper places as quickly as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[96408] = { id = 96408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visitor to Dun Morogh", description = "Last night one of our mountaineers spotted a campfire on a hillside to the east. It looks to be pretty high up, overlooking  the Gol'Bolar Quarry.\n\nIt's probably nothing, but I'd like you to go check on that camp. If they are friendly, no harm done. If they aren't friendly... well, you know what to do.", sourceObjective = "Investigate the campsite overlooking the Gol'Bolar Quarry.", completion = "Greetings, friend. How are ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[96604] = { id = 96604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Brakk's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96605] = { id = 96605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Kaga's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96606] = { id = 96606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Lyreena's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96607] = { id = 96607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Eleanor's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96608] = { id = 96608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Outdoors", description = "Greetings, {class}. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it.", sourceObjective = "Sit near Eric's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", progress = "Having the skills needed to survive the outdoors are critical. A well-rested and well-prepared adventurer has a much higher chance of surviving this lifestyle.", completion = "So now that we've learned the basics, why don't you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.", sourceObjectiveStatus = "unverified-source-field" }
quests[96626] = { id = 96626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Tomas in Goldshire to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96627] = { id = 96627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "{name}, you have proven your competence as a protector thus far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Goldshire. Go and see what he's doing.", sourceObjective = "Speak to Sam Sarsparilla near Goldshire.", completion = "I appreciate the lookin' out, {class}. That marshal's just a worrywart.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96628] = { id = 96628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "Wait, {name}. I have another ask of you, before you brave that tunnel.\n\nMy mountaineers have reported an adventurer that's shown up just outside of Kharanos. Could you deliver these supplies to him?", sourceObjective = "Deliver the Supply Bundle to Eric Brighthammer near Kharanos.", progress = "Are you here to learn about camping in the wilderness?", completion = "You say these are from the mountaineers? Aye, I could use them. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96629] = { id = 96629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Gremlock Pilsnor in Kharanos to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96630] = { id = 96630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", sourceObjective = "Bring the journal to Lyreena Duskblade near Dolanaar.", progress = "Are you here to learn about camping in the wilderness?", completion = "Is that my journal? I've been missing this for a while. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96634] = { id = 96634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Zarrin in Dolanaar to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96638] = { id = 96638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\n\nSeek him out and see what you can learn from him that may help you in your own travels.", sourceObjective = "Speak to Raan Wildwind near Shen'dar Village.", completion = "Well met!", sourceObjectiveStatus = "unverified-source-field" }
quests[96646] = { id = 96646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96652] = { id = 96652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>", sourceObjective = "Bring the journal to Brakk near Razor Hill.", progress = "Are you here to learn about camping in the wilderness?", completion = "Is that my journal? I've been missing this for a while. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96655] = { id = 96655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Cook Torka in Razor Hill to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96656] = { id = 96656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "{name}, you have proven yourself trustworthy in your endeavors against the Scarlet Crusade so far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Brill. Go and see what she's doing.", sourceObjective = "Speak to Eleanor Shackleton near Brill.", completion = "I'm not affiliated with the Scarlet Crusade, if you couldn't tell. I'm just an adventurer stopping by before my next venture into the wilderness.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96658] = { id = 96658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with William Pickman in Brill to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96659] = { id = 96659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer", description = "Wait, {name}. I have another ask of you, before you leave us.\n\nThere is an adventurer by the name of Kaga Wildhoof who has made camp just outside of Bloodhoof Village. She has greatly helped me in the past, and now I see my chance to repay her. Could you deliver these supplies to her?", sourceObjective = "Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", progress = "Are you here to learn about camping in the wilderness?", completion = "Chief Hawkwind sent you? I told him back then I needed no compensation, but it seems he hasn't listened. Thank you, {class}.\n\nHey, you've got the look of an adventurer yourself. How would you like to learn about camping?", sourceObjectiveStatus = "unverified-source-field" }
quests[96661] = { id = 96661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Cooking", description = "So you want to learn more about camping, huh? Good for you, {class}. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp.", sourceObjective = "Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook.", progress = "A good campfire is the foundation to any good camp.", completion = "With this, you'll be able to set up a camp anywhere out in the wilderness. What you've learned is just the basics, so you won't be able to place too many furnishings around it.\n\nRaise your cooking skill and you might just be able to learn to make even bigger fires.\n\nYou can also learn the basics of furnishing your campsites from other tradeskill trainers if you're savvy in their skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[96735] = { id = 96735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toast!?" }
quests[96774] = { id = 96774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Gurubashi Idol", description = "The ancient Gurubashi of Stranglethorn Vale were da masters of dark blood magics. Rumors be they'd use pure truesilver idols to channel that bad bad voodoo.\n\nOl' Mazu'kon would love to get his hands on one of those idols... for academics ya see. How 'bout you gather some friends and do a bit of smash and grab on that drowned city stickin' out the ocean off the coast of Stranglethorn? Kill the most impressive lookin' priest ya can find in there, and they sure to have what I be lookin' for.", sourceObjective = "Recover an Ancient Gurubashi Idol from the Drowned City.", sourceObjectiveStatus = "unverified-source-field" }
quests[96779] = { id = 96779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syndicate Sabotage", description = "Sometimes, {race}, a single cut in the right place will drop a foe dead. The same is often true of organizations.\n\nOur agents have identified a key target among the ranks of the Syndicate: a man by the name of Lord Tomas.\n\nHe plays an instrumental role in the functions of Durnholde Keep, in Hillsbrad Foothills. If you wish to be of service to Ravenholdt, go to Durnholde and eliminate him. The quicker, and quieter, the better.", sourceObjective = "Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform.", sourceObjectiveStatus = "unverified-source-field" }
quests[96781] = { id = 96781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's the Big Idea?", description = "We have noticed a Syndicate scouting party prowling around the ruins of Alterac, led by a man named Barton.\n\nThey're clearly searching for something, but I cannot know what without reading his scouting reports.\n\nI ask that you pickpocket the report from him, rather than killing him outright. Barton's death will tip off the Syndicate that we're on to them, and they will certainly take counter-measures to cover their tracks.\n\nIf you hope to find him, he is most likely among the Syndicate at Strahnbrad.", sourceObjective = "Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor.", sourceObjectiveStatus = "unverified-source-field" }
quests[96782] = { id = 96782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covert Extraction", description = "It seems our friend Barton here has made this very easy for us. He is after two heirlooms of the Perenolde family within the ruins of Alterac. The Blade of House Perenolde, a sword, and the Royal Aegis of Perenolde, a shield.\n\nFrom the report, it seems these armaments are within two towers among the ruins. Best we acquire them before the Syndicate does.\n\nThe ogres occupying the ruins are fierce, but I trust you should be able to sneak past them without needing to bloody your blade at all.", sourceObjective = "Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform.", sourceObjectiveStatus = "unverified-source-field" }
quests[96783] = { id = 96783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Way In", description = "Stromgarde Keep is one of the Syndicate's largest strongholds. Many of the organization's most important dealings take place behind its walls.\n\nI have received word of a certain trade taking place between members of the Syndicate somewhere in Arathi Highlands, and I'm certain the details of this trade can be found somewhere in Stromgarde.\n\nTo infiltrate the keep without arousing suspicion, you'll need a disguise. See if you can find one among the Syndicate outside the keep, at Northfold Manor.", sourceObjective = "Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[96784] = { id = 96784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Disguise", description = "<You recall Myrokos' instructions to find out about an important deal going on with the Syndicate in Stromgarde Keep. With your disguise, you should be able to talk to members of the Syndicate somewhat freely. Surely, one of them knows something.>", sourceObjective = "While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[96785] = { id = 96785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ain't No Telling", description = "Who do you think you are? Showing up and sticking your nose in official business.\n\nI'm not telling some rookie anything about the higher-up's dealings without good reason. Unless you've got something important, or valuable, for me, I've got nothing to say to you.", sourceObjective = "Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[96786] = { id = 96786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Syndicate Sting", description = "Falconcrest sent some guys to do a handoff at the southern part of Thoradin's wall. I don't know what they're picking up. Must be good, because everyone involved has kept it a total secret. I don't think the guys picking it up even know what it is.\n\nThat's all I've got. Don't make me regret telling you that.", sourceObjective = "Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", sourceObjectiveStatus = "unverified-source-field" }
quests[96800] = { id = 96800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Due", description = "You there, {class}. I have a matter I could use assistance with.\n\nI just so happen to be writing a thesis on the ancient Wildhammer runemasters of Grim Batol, and there's a particular tome I need to complete my research. According to our ledgers, a mage by the name of Doan checked the book out of the old Dalaran library before the Third War and never returned it!\n\nArcanist Doan is now holed up in the Scarlet Monastery in Tirisfal Glades. Retrieve this book for me and you'll be well rewarded.You will be able to choose one of these rewards:", sourceObjective = "Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery.", sourceObjectiveStatus = "unverified-source-field" }
quests[96821] = { id = 96821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legging It", description = "We see fewer and fewer travelers from Razor Hill these days. The scorpids were never much fun, but now I hear there are spiders making their nest along the road.\n\nIf your travels take you up north, kill some of the spiders on your way. Then, let Razor Hill know the path's a bit safer for them.", sourceObjective = "Kill 6 Ridgeshade Creepers and 6 Ridgeshade Lurkers in southern Durotar, then report to Gar'thok in Razor Hill.", completion = "The peons have been scared to travel south for some time, {name}. Now that you've cleared the path a bit, we can get them back to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[96822] = { id = 96822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Honor", description = "We lost many brave warriors of the Horde when we sacked Tiragarde Keep. Now that the humans have reinforced the ruins, we cannot collect their remains to properly honor their deaths.\n\nGo to the ruins surrounding the keep, and search for the weapons left by our fallen kin. We will display them in a place of honor.", sourceObjective = "Collect the Raider's Battleaxe, Raider's Bow, and Raider's Shield from the Tiragarde Keep outskirts, then return them to Turroc in Razor Hill.", progress = "Have you done what I asked?", completion = "These warriors will always be remembered, {name}. You have made sure of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[96825] = { id = 96825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Fruit Could Bite Back", description = "Our hunters and fishers bring back plenty of savory food for our troops - but it's rare that they get a sweet treat.\n\nI've seen a cactus that produces a prickly, tasty fruit. But it only grows in the hills to the west, where the wretched quilboars make their camps. Make your way past the quilboars and bring me some of those fruits. And be careful - the fruits are as spiny as the quilboars!", sourceObjective = "Cook Torka in Razor Hill wants you to collect 8 Prickly Pear Fruit from the Razormane Grounds west of town.", progress = "Did you find the fruits?", completion = "I'll use these to prepare something tasty, and save the seeds for planting. Someday we'll have prickly pears growing all around Orgrimmar!", sourceObjectiveStatus = "unverified-source-field" }
quests[96873] = { id = 96873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pain in the Neck", description = "The trolls east of here have lost their will to the witchdoctor, Zalazane. He uses many cruel magics to keep hold of his prisoners' minds, but one of his favorite tricks is to make them wear pendants wrapped in evil binding spells.\n\nPractice your enchanting skills by stripping the magic from these pendants, and bring me the results. And don't accidentally put one around your neck, if you value your freedom!", sourceObjective = "Pa'zula in Sen'jin Village wants you to collect 3 Luminous Residue. Luminous Residue can be obtained by disenchanting Hexed Pendants dropped by trolls in the Echo Isles.", progress = "What do you have for me, {name}?", completion = "Fine work. A shame about the slain trolls, but with the binding spells removed, their spirits can rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[96874] = { id = 96874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Spinal Axe", description = "Have you seen the huge beasts of Thunder Ridge? I keep thinking the spines on their backs would be perfect for crafting the head of a mighty axe. Saru laughed when I told him... but what does he know!?\n\nAs part of your smithing lessons, you can help me out! Bring me some of those spines, along with grinding stones to sharpen them.", sourceObjective = "Ug'thok in Orgrimmar wants you to collect 5 Weathered Spines from beasts in Thunder Ridge, along with 5 Rough Grinding Stones.", progress = "Yes?", completion = "These spines are tougher than I expected, {name}! Crafting with them may not be as easy as I thought... but I'll keep working on it!", sourceObjectiveStatus = "unverified-source-field" }
quests[96875] = { id = 96875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Thunder Ridge", description = "Orgrimmar is always expanding, {class}. And when the peons need hides to line the walls and roofs of our new buildings, they come to me!\n\nThe hides of the lizards in Thunder Ridge are typically too thick for armor, but they make excellent building material. Bring me some of their hides, along with a few lighter cured hides. Let's see your skill with leather!", sourceObjective = "Kamari in Orgrimmar wants you to collect 5 Rough Lizard Hide from beasts in Thunder Ridge, along with 2 Cured Light Hides.", progress = "Yes?", completion = "Your work helps Orgrimmar grow. Know that as you walk the city's paths.", sourceObjectiveStatus = "unverified-source-field" }
quests[96876] = { id = 96876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ukor's Lost Pack", description = "The pack has the name \"Ukor\" crudely stitched along the flap.", sourceObjective = "Return the pack to Ukor in southern Durotar.", progress = "Something need doing?", completion = "My pack! When I dropped it to run from that huge spider, I thought I'd never see it again. You really are a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[96877] = { id = 96877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halikor's Hoof", description = "The enormous hoof serves as proof of your victory over the mighty lizard.", sourceObjective = "Deliver Halikor's Hoof to Orgrimmar.", progress = "Yes?", completion = "What a trophy, {class}! That must have been some fight!", sourceObjectiveStatus = "unverified-source-field" }
quests[96895] = { id = 96895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Emissary", description = "Not sure if you heard, but two emissaries of the Argent Dawn just passed through here. I don't mind the Argent Dawn, but I don't like them poking around Tirisfal unsupervised either. They were both Forsaken... but that doesn't make me any less nervous.\n\nOne of them just passed by here, headed southeast. There's a group of scourge cultists snooping around the outskirts of the city in that direction. If those two heard about them, there's no doubt that would have caught their attention.", sourceObjective = "Find the Argent Dawn member near the entrance to the Undercity.", completion = "Stay low and try not to be seen, {class}. These cultists are not to be trifled with.", sourceObjectiveStatus = "unverified-source-field" }
quests[96896] = { id = 96896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Righteous Cause", description = "Danitha and I fought against the scourge in the defense of the Undercity when Naxxramas attacked. We lost many good friends that day, including the hero after which this keep was named--Garek Bandarion.\n\nHe might just have been the first Forsaken to rediscover how to wield the light as a paladin. I am encouraged to see his legacy and potential live on here with Danitha and her cohort.\n\nIf only the rest of the forsaken felt the same way...", sourceObjective = "Observe the conversation between Danitha Morr and Leonid Barthalomew the Revered.", completion = "I plan to stay here for a time and speak with more of my friends, but I will return to Light's Hope Chapel in Eastern Plaguelands soon enough. Should you ever find yourself out that way, please do say hello. We could always use more help from able-bodied adventurers.", sourceObjectiveStatus = "unverified-source-field" }
quests[96897] = { id = 96897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cult of the Damned", description = "The scourge are a blight on our lands, and their living servants are the worst of them. The people of Tirisfal have enough to deal with between the mindless dead and the Scarlet Crusade. If you wish to do some good, help me put an end to this scum.", sourceObjective = "Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades.", completion = "Thank you for your aid, {class}. If we do not wish to see Lordaeron's history repeat itself, we've got to be vigilant when threats like this spring up.", sourceObjectiveStatus = "unverified-source-field" }
quests[96898] = { id = 96898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of War", description = "It wasn't long ago that the citadel of Naxxramas bore down upon this city, intent on wiping the Forsaken off the map. Both the Forsaken and the Argent Dawn lost much that day to secure the future of the Forsaken.\n\nDuring the battle, the great necrotic focusing crystal hanging beneath Naxxramas was shattered and its fragments were scattered all over this area. I suspect that is what the cultists are here for. Help me recover the fragments and deprive the scourge of them.", sourceObjective = "Gather 12 Necrotic Crystal Fragments in Tirisfal Glades.", progress = "I'd advise you not come into too much physical contact with those crystals. Even shattered and spent, the lingering magic in these necrotic crystals is highly dangerous.", completion = "Thank you. This should slow the efforts of the scourge in this area. I suspect the denizens of Tirisfal will be pulling these crystals out of the ground for years, but removing the most conspicuous of them can only help.", sourceObjectiveStatus = "unverified-source-field" }
quests[96899] = { id = 96899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandarion Keep", description = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\n\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess.", sourceObjective = "Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades.", completion = "This place is full of memories for me. This place was once held by the Argent Dawn. It was here from here that we prepared for many battles and skirmishes against the scourge during their most recent push into Tirisfal Glades.\n\nWhen we withdrew to the Plaguelands I feared it would fall into disrepair. My fear was well-founded, but I am glad that Danitha and her paladins have taken over stewardship of it now.\n\nShe even named the keep after... a mutual friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[96984] = { id = 96984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Disruption", description = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\n\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\n\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe.You will be able to choose one of these rewards:", sourceObjective = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", sourceObjectiveStatus = "unverified-source-field" }
quests[96986] = { id = 96986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grave Knight", description = "Within the underbelly of the mage city to the north is a traitor to our kind. A necromancer of disturbing talent. He raises an army of undeath right under the Kirin Tor's nose.\n\nI care not for the fate of the mage city, {name}, but this grave knight spits in the face of everything we Forsaken stand for. Put an end to him. Show him no one is beyond the reach of the Dark Lady.You will be able to choose one of these rewards:", sourceObjective = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.", sourceObjectiveStatus = "unverified-source-field" }
quests[96987] = { id = 96987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunistic Education", description = "Well if it ain't a like-minded entrepreneur. Sneakin' into Dalaran durin' such troublesome times? Tsk tsk.\n\nMy kinda {race}!\n\nWhile our mage friends here are occupied, maybe we could find ourselves some 'misplaced' treasures. They gots whole libraries dedicated to fancy arcane magics. If you could bring me one of their secret tomes, I could sell it for a pretty penny. Split the profits with ya.\n\nHey hey don't look at me like that. You ain't exactly here on a field trip yourself. You want in or what?You will be able to choose one of these rewards:", sourceObjective = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.", sourceObjectiveStatus = "unverified-source-field" }
quests[96988] = { id = 96988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Source of Power", description = "With the city of Dalaran under siege by their own constructs, this is the perfect opportunity to, let's say, borrow a few samples.\n\nImagine an army of arcane-powered abominations. The Dark Lady would have no choice but to recognize my alchemical prowess. Maybe even grant me head of the Royal Apothecary Society?\n\nGo to the city and find the constructs' cores. They are unlikely to give them willingly, so do what you must.You will be able to choose one of these rewards:", sourceObjective = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[97003] = { id = 97003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chol'aruk the Ravener", description = "You there, {class}. I need your aid. There are rumors of a beast that makes its lair deep in a cave at Thorn Hill, northeast of here. The Razormane call it Chol'aruk or \"The Ravener\". It's supposedly five times the size of a normal quilboar with a thirst for blood that can never be sated.\n\nMost don't believe the tales. But I do--because I've fought its like before.\n\nSeek out its lair and slay Chol'aruk. Bring me its head. I warn you though--prepare well and do not go alone.\n\nBlood and thunder, {class}.", sourceObjective = "Bring the head of Chol'aruk to Gur'ak in the Barrens.", progress = "It took the strength of six skilled fighters to defeat one of these creatures, and it still managed to fell four of us before we could put it down.\n\nIf these monstrous beasts were to appear in greater numbers, the damage that the qullboar could inflict upon the land could be catastrophic.", completion = "Impressive, {class}. None will doubt my tales when I return to Orgrimmar with this grim proof of the existence of these abominations. Rest assured this glory is yours however, and I will speak loudly of your deeds.\n\nLok-tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[97005] = { id = 97005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chol'aruk the Ravener", description = "There's rumors of a monstrous abomination that makes its lair at a cave to the northwest of here, on the plateau known as Thorn Hill. The Razormane call it Chol'aruk or \"The Ravener\" and those that have seen it say its so massive that it can swallow an orc whole.\n\nFew believe such tales, but I do... because I've fought one like it myself. On the honor of those I lost to these things, this beast must die.\n\nGather strong allies and find the lair of Chol'aruk. Kill the abomination and bring me it's head.", sourceObjective = "Bring Chol'aruk's Head to Bainham in the Barrens.", progress = "It took six of us to defeat one of these creatures, and it still managed to kill all but myself and one other before we were able to bring it down.\n\nThis far from alliance lands I should leave it well enough alone. Light knows I'll lose little sleep over a few tauren savages or orcish brutes. However, the honor of my fallen brothers demands action.", completion = "My dead men will rest easier knowing that there is one less of these monsters in the world. You've done well, and are a true and stalwart defender of the alliance. Thank you.\n\nGo with honor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97047] = { id = 97047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cook in the Cage", description = "Hey! You! You have to help me! I was just out exploring the jungle when, all of a sudden, I was ambushed by these maniacs! I don't know what they plan to do with me, but I've heard talk of tigers and headshrinkers, and I don't want part in either!\n\nI don't know how, but you have to get me out of here! Please! A key to this cage, a disguise to sneak out, something! Anything!", sourceObjective = "Find a key to Wendel's cage, and a disguise for him to sneak out, within the Kurzen compound.", sourceObjectiveStatus = "unverified-source-field" }
quests[97048] = { id = 97048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning to Port", description = "Listen, I can't repay you right now, but I'm a cook on Captain Aransas' ship. I'll be sure to put in a good word for you when I get back to Booty Bay. You should speak to the captain when you get the chance. I'm sure she'll be grateful to have me back.You will be able to choose one of these rewards:", sourceObjective = "Speak to Captain Aransas in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[97065] = { id = 97065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tip the Scales - Keefer's Angelfish" }
quests[97066] = { id = 97066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tip the Scales - Brownell's Blue Striped Racer" }
quests[97067] = { id = 97067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tip the Scales - Dezian Queenfish" }
quests[97220] = { id = 97220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Philmor's Favor", description = "Every day this week we've been short dockhands.\n\nCare to ease the stress on our cargo schedule?\n\nTake this package to the stockroom entrance of the Gatehouse. You'll find it inside Trias' Cheese shop on the second floor. The mistress, Elaine, will be quite familiar with the deliveries. The Gatehouse often has shipments arriving with more discretion to allow for ceremonial surprises on behalf of the guard's officers.", sourceObjective = "Bring the Gatehouse Shipment to the stockroom entrance located in Trias' Cheese shop in the Trade District", progress = "You looking to fill a crate with our finest aged wheels?", completion = "Oh, dear. You think we want to carry that up the stairs ourselves? Keeping the valuables intact is your responsibility up until the point you drop it off.", sourceObjectiveStatus = "unverified-source-field" }
quests[97222] = { id = 97222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatehouse Goods", description = "Yes, it's only a flight of stairs, but if it's such a small ask, it should be no problem for you to finish the delivery yourself! \n\nTrias' Cheese isn't part of the Gatehouse or their stocking inventory, but our buildings share a floor.\n\nPlace the crate outside their stockroom door--the guard will send someone for a regular pickup. They will see the package arrival and carry it inside as they return to post.", sourceObjective = "Carry the Gatehouse Shipment up the stairs in Trias' shop and leave it outside the door.", completion = "Yep. There's a reason that hinge opens inwards towards them, so they don't get the door blocked by people leaving stuff anywhere they please.\n\nConsider us professionally acquainted, {class}. \n\nWe respect your business, and expect you to respect ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[97223] = { id = 97223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodtalon Matriarch", description = "All of the raptors you see before you are ones I have trained myself. They come from all over Kalimdor, but some of the finest come from the Bloodtalon raptors on the isles off our coast.\n\nOne raptor amongst them, the Bloodtalon Matriarch, is particularly savage and has killed many from our village and has become too dangerous to leave at our borders. If you can strike her down, return with her eggs so that we can raise the hatchlings as allies instead of enemies.", sourceObjective = "Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village.", progress = "The Bloodtalon are known for their cunning and swiftness, and make fine companions when raised from egg to adult.\n\nUnfortunately adult raptors are very difficult to train, and I have tried to capture the Matriarch on more than one occasion. But she had become too dangerous of late.\n\nStill I hope to preserve her legacy by raising her children as companions here in Sen'Jin.", completion = "Thank you, {name}. I am happy we will be able to preserve her bloodline and raise them to be our allies. You have done a great service for our tribe.", sourceObjectiveStatus = "unverified-source-field" }
quests[97225] = { id = 97225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Loa Idols", description = "When we fled the isles that Zalazane and his ilk now inhabit, we left behind many precious idols that help us commune with spirits we worship: our loa. They are of grave importance to our tribe.\n\nThe followers of Zalazane show no reverence for our loa and have scattered these idols across the largest of the isles.\n\nThis is an action that will not go unnoticed if we are not able to collect these idols, and offending a loa is a grave matter.\n\nGo, find as many loa idols as you can and return them to me.", sourceObjective = "Collect 8 Forgotten Loa Idols from the Echo Isles. Bring them to Master Gadrin in Sen'jin Village.", progress = "Have you found our loa idols, {name}? We must begin our rituals again soon.", completion = "You have done a great deed for our tribe today.\n\nUnlike some tribes, our kinship with our loa is one of reverence and respect, and we owe them much.\n\nI would not want the Darkspear to fall out of favor with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[97234] = { id = 97234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading Room", description = "Are you here to discuss the deeper meanings of our storied legends? No?\n\nWell, after you're done looking around, can you carry this to the library for me? We're exchanging some of our less popular bodies of work for some more modern writing. I have a list of tomes I'm quite sure the librarian will be able to procure for us within our existing arrangement.\n\nComplimentary club refreshments on us, if you help us out.", sourceObjective = "Bring the wrapped reading material to the Stormwind library.", progress = "Please keep your voice down.", completion = "Let's see here. Roy's Book Club, isn't it? I recognize this wrap technique. \n\nWell, if he says this is what people want to talk about, it's all fine by me. The material we receive back is always in as good of quality as we loaned it, so we know they're treating it with respect regardless of how provoking the words may be.", sourceObjectiveStatus = "unverified-source-field" }
quests[97236] = { id = 97236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang of Githyiss", description = "A fresh specimen from a beast of this size is quite a find. Perhaps someone in Aldrassil familiar with the study of spiders would be interested in the fang.", sourceObjective = "Deliver the Fang of Githyiss to someone interested in the study of spiders in Aldrassil.", completion = "My, my. How I do love surprises, {name}.\n\nThis specimen will surely help further my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[97237] = { id = 97237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shelf Picked", description = "I've checked our inventory and all of the selections Mr. Lewells has listed are currently available.\n\nYou will, however, need to procure them off the shelves yourself. Part of our librarian duty is vigilance, and for that, I will resume supervisory bookkeeping.\n\nReturning with the material to Roy on his behalf will not mark yourself accountable for their return; as with his note you're serving as the book club's official courier. Their establishment shall carry that burden.\n\nGood day, {name}.", sourceObjective = "Find each of the reading materials located somewhere in the library and then return to Roy Lewells in Stormwind's Park.", progress = "You forgot what you had to do the moment you stepped through the door, eh? Happens to everyone.", completion = "These are them! Some of them even smell exotic! Fantastic, I can't wait for us to have lively conversations about these writings.\n\nCellar after hours, of course.\n\nThanks for the quick errand run, {name}. As promised, it's on the house. We keep our word here.", sourceObjectiveStatus = "unverified-source-field" }
quests[97242] = { id = 97242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yelmak's Medley", description = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\n\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\n\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood.", sourceObjective = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions", progress = "We discover formulations and recipes by showing old ingredients to new generations, who experiment with it in their own way.", completion = "This type of cattail and speargrass is unique to Orgrimmar. Drinking from Azshara mountain spring water, and nourished by the sweat and blood soaked mineral dust of our rocky land, these herbs contain potent powers locked within.\n\nI'll give these to Yelmak, who may be able to win back Whuut's ear with a hands-on lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[97243] = { id = 97243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Even though we are in the realm of skywall, this is still the elemental plane. The spirits of all four elements speak to us, if we deign to listen. One among us Windshapers is in particular attunement with the element of fire. A shen'dorei by the name of Olariaan Swiftburn.\n\nBring this to him at the Shrine of Flames in the Gustberry Lowlands. You'll find it tucked away along the edge of the island, west of Valanaar.", sourceObjective = "Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands.", progress = "Yes, {name}? What do you have there?", completion = "So you've brought the torch. Yes, young {class}, I can teach you to heed the call of fire. It will not be easy, but nothing that we do in this realm is ever easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[97244] = { id = 97244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "There is an Al'Aketh Skypriest called Faladiel. He was once a caller of the flame and a stalwart Windshaper. Like so many Al'Aketh, he mortgaged his loyalty for power and his hands are now stained with the blood of  his former brothers and sisters.\n\nYou will find Skypriest Faladiel at the farm to the northeast past Valanaar, just to the south of the Shrine of Akir. Kill the betrayer. Bring me his heart. It is a gruesome task, but it is needed for the ritual we are to perform.", sourceObjective = "Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart.", progress = "The heart of a betrayer is a powerful reagent. The flames will eagerly accept such an offering and burn more intensely as it is consumed.", completion = "The Windshapers do not forget, and blood is always paid with blood. It pleases me that you were able to deliver this final, painful reminder of our creed to this traitor.\n\nThis heart will not be all that feeds the flames today, however. There is one other task that needs to done.", sourceObjectiveStatus = "unverified-source-field" }
quests[97245] = { id = 97245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "The residents of the Shen'dar Highlands speak of an ancient forest sprite called Kuramaa. They say it lives inside of a twisted stump at the summit of a hill near the highlands Anchor Pylon.\n\nGo to the highlands and find this stump. Rap your fist upon the bark and Kuramaa will appear. Best the spirit in combat, and bring me its wooden mask.\n\nBe warned however, this entity will be exceptionally resistant to much of your magic. Only the touch of flame will lay low the spirit.", sourceObjective = "Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.", progress = "The spirit of Kuramaa is eternal, and it will manifest again when it is needed. It's mask is a source of great power, and will prove invaluable to the ritual we must complete.", completion = "We now have what we need. We will light the eternal flame and commune with the spirits of fire.", sourceObjectiveStatus = "unverified-source-field" }
quests[97246] = { id = 97246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meal Appeal", description = "My son, Migi, always takes off to play with his friends all day. I tell him to pick up a lunch at Borstan's, but I know he almost never does, because he comes home starving. These kids think their games are more important than their own bodies!\n\nPlease, stop at Borstan's Firepit and tell him you're there to deliver Migi's lunch. You can almost certainly find Migi behind Grommash Hold with the rest of his friends.\n\nDuties keep me here during the day and I can't watch over his every meal.", sourceObjective = "Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally.", completion = "Of course. Migi's parents and I have an arrangement to give Migi a bagged lunch every day, but I can only ensure the boy gets his food if he actually comes in to pick it up.\n\nSometimes, he doesn't pick up his meal multiple times a week, and I wonder where he gets the energy to stay out and play.", sourceObjectiveStatus = "unverified-source-field" }
quests[97249] = { id = 97249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favorite Food", description = "Now that I know his parents worry about how much he's actually filling that belly, I've got an idea. \n\nThey made me promise not to pack the same meal every day, so Migi grows a taste for more than one thing. Still, whenever the smoker's full and we're making sweetglazed hog belly sandwiches, he always shows up for lunch. We've started crumbling the leftover crispy glazed bits as a topping--something we can add daily. \n\nTake this to him. Maybe he'll start showing up early and bringing friends!", sourceObjective = "Bring Migi's Lunch to him behind Grommash Hold", progress = "I think we can win this one...", completion = "Borstan's Meats? Is that for one of us?\n\nOh!\n\nWow... this smells really good! Yummy.\n\nThanks for bringing me my lunch. I can tell what Borstan is going to be serving daily when my friends and I walk the road to Grommash Hold, by the smells alone. This tastes like my favorite, the sweetglaze! But it's different. I like the strong flavored crumbs.\n\nIf it's going to be this tasty every day, I think we need to stop our game to take our lunch together!", sourceObjectiveStatus = "unverified-source-field" }
quests[97250] = { id = 97250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrongly Blamed, Justly Corrected", description = "Traveler, have you plans to head toward Dustwallow Marsh? I have heard mutterings that a few human soldiers have taken a stand at its border and are toppling the landmarks left behind by our tauren pathfinders.\n\nRumor has it that a favored tavern has burned to the ground, and in typical Alliance fashion, they immediately cast their blame onto the Horde! I cannot know whether there is any truth to their claim, but their incursion onto OUR land must not stand.\n\nKill first, investigate later!", sourceObjective = "Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.", completion = "So the rumors were true! I expected as much, tensions have been rising along the eastern coast for some time. I knew it would only be a matter of time before conflict crept into our territory.\n\nHowever, I am skeptical that we played a role in the tavern's destruction. Too many Horde civilians rely on that route for trade and travel. Perhaps you could investigate further if you find the time.\n\nIn any case, today's deed is a victory for the Horde, and a stern warning to the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[97253] = { id = 97253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts and Pieces", description = "Hey, got a sec?\n\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\n\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?", sourceObjective = "Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.", progress = "Not another word out of you until your pockets are jingling with metal!", completion = "Whooooa! Nice one, pal! You saved me from another one of Gagsprocket's unbearable lectures on the cost of metal. More importantly, I can jump right into building my next prototype.\n\nUhhh, I didn't have a reward planned... Do you like boxes?", sourceObjectiveStatus = "unverified-source-field" }
quests[97257] = { id = 97257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Now we will perform the ritual. \n\nI will place the materials onto the altar and call forth the spirits of flame. If the offering is accepted, they will appear and light the Eternal Flame. You will then hold your torch forth and capture the flame.\n\nCarry the lit torch to Valanaar and place it in the Brazier of Eternal Flames. You must do so quickly, for the flames of the Firelands are quick to dissipate here in Skywall.", sourceObjective = "Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\n\nYou must deliver the Eternal Flame to Valanaar before the timer runs out.", progress = "You have done well to come this far. You do the Windshapers honor, {name}.", completion = "It is done. The Eternal Flame burns once again.\n\nYour trial is now complete. I am pleased to present you with your Fire Totem. Use this icon of power well in your travels, {name}. \n\nJust remember, the power of the elemental plane serves those that respect it, and consumes those who do not. This is our way.", sourceObjectiveStatus = "unverified-source-field" }
quests[97263] = { id = 97263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Package Has Arrived", description = "<Several misplaced packages have been left by the mailbox. You note that one of them is marked for delivery from Aerie Peak, to Ironforge, to Eldrun Stormbreaker. It is marked \"urgent.\">", sourceObjective = "Deliver Eldrun's misplaced package.", progress = "What's that you've got there?", completion = "What! I've been going to the mailbox by the bank every day looking for this package! This city needs to figure out its layout. Not easy to navigate like Aerie Peak!\n\nLet's see what I've got... totem carving tools... spare axe... some kind of goblin device? I didn't order that! Ah, I'll just send it back.\n\nEr, uh... I mean... thank you for bringing all of this to me. Here's a little something for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[97265] = { id = 97265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hate the Hatefury", description = "Ever strike a deal with a satyr, mon?\n\nI have. How could I resist? The promise of power, knowledge far exceeding what any ordinary tome could offer... all alongside an eager and charismatic minion. What more could I ask for?\n\nBah, of course they would never bend the knee to a mortal. I bargained when I had nothing, only to be cast aside with even less.\n\nNow, I want revenge. Revenge against the Hatefury. Raid their camp to the northeast! Stain the dirt with their foul blood.You will be able to choose one of these rewards:", sourceObjective = "Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[97275] = { id = 97275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whuut's the Rush", description = "Whuut is a prodigy. That much is true. But he doesn't yet have the experience, wisdom, and time on the stirring rod to know how to respect alchemical processes.\n\nHe is exhausting all of the rarest and most exotic reagents we have available without pausing to practice and refine his basic skills.\n\nGive him this potion I've brewed with a quick tonic method. He'll reconsider everything he's doing when he learns how local remedies and careful touch are the first true mastery.", sourceObjective = "Give Yelmak's Potion to Whuut.", progress = "Alright, what's next... Black Lotus, Mountain Silversage...", completion = "Grorru--whaa?\n\nYou say Yelmak made this potion from speargrass and cattail with no other reagents? I didn't know chemists had any real need for these common plants we see every day.\n\nMaybe he's right. There could be a lot I'm missing out on by skipping to the most rare and least-studied flora first.\n\n{name}, take your pick from one of these potions I brewed earlier. I appreciate you taking the time to visit our shop.", sourceObjectiveStatus = "unverified-source-field" }
quests[97277] = { id = 97277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund and Gozwin", description = "Oi, had me back turned gettin' the boar roast ready when I heard me pal Gozwin screamin' fer his life!\n\nWicked fangs and a blur are all I saw when I turned. Such huge paws! A snow leopard was draggin' its gnomish catch away. I grabbed me shotgun and fired above the beast. It dropped him and sprinted off.\n\nLuckily, it hadn't done more than give ol' Goz some deep scratches.\n\nHead back to camp in the northwestern hills and retrieve Gozwin's Mechanic's Log. Kill that snow leopard too if you see it!", sourceObjective = "Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler.", progress = "Poor Goz is more concerned for his mecha-walker than himself. Says if anyone gets a hold of that mechanic's log he's greased. Hah! That's why I told him he should just leave his work at home!", completion = "Aye, I'm not surprised to hear that snow leopard was makin' a meal of the boar we were fixin' fer roastin'!\n\nGoz will have one less thing to stress about now that you brought back his log book. Maybe now he can focus all his energy on gettin' back on his feet.\n\nThanks, {name}. Take a little something as a token of my appreciation, fer makin' the trek, and fer protectin' the hills.", sourceObjectiveStatus = "unverified-source-field" }
quests[97279] = { id = 97279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayward Weapons", description = "With an influx of new recruits like yourself, it's been hard to keep our weapons supplied. Our weaponsmith, Kzan, is running low on training weapons and I'd like to see what kinds of skills you possess to get an idea of what I have to work with. Luckily for you, I have a solution to both.\n\nWhile you're out there cutting your teeth on boars, salvage six abandoned training weapons. Our failed recruits left them laying on the ground. Once you do, return them to our weaponsmith Kzan behind me in the Den.", sourceObjective = "Collect 6 Abandoned Training Weapons, then return to Kzan Thornslash in the Den.", progress = "Throm'ka, {class}. Gorak told me I should be expecting you. It is good to see you in one piece!\n\nWere you able to collect the training weapons I requested?", completion = "Thank you for returning these weapons, {name}. I will get to work repairing them for the next wave of recruits.", sourceObjectiveStatus = "unverified-source-field" }
quests[97281] = { id = 97281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simmering Storm", description = "<Before you is a strange orb and with a dull surface. When picked up a small electrical current seems to vibrate from within. Upon closer inspection, it looks as if a dark mist swirls within and every so often a small electrical spark can be seen.\n\nIt is clear the harpy was using it for some purpose. Perhaps Rezlak would be interested in this object?>", sourceObjective = "Bring the Dull Stormy Orb to Rezlak near Drygulch Ravine.", completion = "Woah, where did you find a neat thing like that? Ya know it reminds me of the other thing my boss Gazlowe always used to tell me...", sourceObjectiveStatus = "unverified-source-field" }
quests[97282] = { id = 97282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormy Potential", description = "\"Rezlack, when an opportunity come's knocking make sure you're ready to seize it.\" That's another gem Gazlowe taught me and that's exactly what I intend to do.\n\nThis orb doesn't seem damaged, it just looks like it's out of juice, but I've the idea to supercharge it back to full strength!\n\nThere are a bunch of thunder lizards in a gorge west of here. They have organs that hold a strong electrical charge that would be perfect for this.\n\nGo harvest some and bring them back to me!", sourceObjective = "Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine.", progress = "It might come as a surprise that with a name like thunder lizard they shoot lightning instead of roaring like thunder.\n\nWell, they do. Shoot lightning, I mean.\n\nTrust me, it's a lesson you only get to learn once if you're lucky.", completion = "Hey, thanks pal! You've been a really big help to me here and I appreciate it.\n\nHere's to hoping I can get this all charged up using these organs. I bet it'll make those no good harpies think twice about attacking my caravan again. I sure hope this works.\n\nEither way you've done your side of the deal. Take this for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[97284] = { id = 97284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriel's Vengeance", description = "If Malem is still alive, then I suspect the Burning Blade orcs are expecting someone to come searching for her soon enough. They will certainly be ready for a fight.\n\nI would prefer if you kept a low profile and stayed out of their way, but the far more likely reality is that they will be looking to meet you, blade to Burning Blade, at every opportunity.\n\nSo how about we plan to keep score from the start. Kill as many as you can, and I'll make it worth your time.", sourceObjective = "Slay Burning Blade orcs at Thunder Axe Fortress in the Desolace, then return to Vahlarriel Demonslayer at Nijel's Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[97286] = { id = 97286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Access", sourceObjective = "Your actions show you are one who respects knowledge. The library is open for use in your studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[97287] = { id = 97287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrewd Negotiations", description = "You have done well to infiltrate the city of mages, but I believe it is time for us to be more... negotiatory.\n\nAs much as it pains me to admit, there is no other place on Azeroth with such a vast knowledge of the arcane. My brilliant work still pales in comparison to the ancient wisdom the Kirin Tor have amassed over the years. I think it's high time we are granted access to this exclusive order, don't you think?\n\nTake the mote you acquired. They will surely give anything to get it back. Anything.", sourceObjective = "Speak with Archmage Celindra in the City of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[97288] = { id = 97288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Torment", description = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\n\nSomeone in the Undercity would know more about this unique abomination.>", sourceObjective = "Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.", progress = "What have we here?", completion = "Oho! I believe I know this head. A cruel joke by our Dark Lady. A delicious one at that.\n\nI think I have a use for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[97289] = { id = 97289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Torment", description = "We craft abomination heads all the time, but this one is special. It belonged to a Grand Marshal of the alliance once. A particularly unpleasant one. Othmar, I believe its name was. The Dark Lady had the pleasure of dispatching of this one herself.\n\nOoh the secrets it could tell if it could talk. And it can! If we reattach it to an appropriate host.\n\nGo ahead and place it next to the available body in the next room. But don't attach it. Not yet.", sourceObjective = "Bring the Head of the Baron to the body of Othmar in the Undercity.", progress = "<The abomination remains lifeless without a head to control it.>", completion = "<The body twitches to life, panicking as it relives its final moments.>\n\nYou...", sourceObjectiveStatus = "unverified-source-field" }
quests[97290] = { id = 97290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Torment", description = "You... abomination...\n\nWhy should... help you...\n\nBe gone...", sourceObjective = "Report your findings to Master Apothecary Faranell in Undercity.", completion = "Not cooperating, eh? Excellent. I always love a challenge.", sourceObjectiveStatus = "unverified-source-field" }
quests[97291] = { id = 97291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Torment", description = "With the head reattached, all we need now is to bind it to the Dark Lady's will. This should not be a problem. The beast barely has brains left as it is after all the beatings it's taken.\n\nWe simply need to motivate it.\n\nFetch me a Toxic Skullcap from Miss Grisette in the Trade Quarter. Oh, and some Blisterweed from our local herbalist trainers, the Alliestars. Feel free to just take some, they owe me. And lastly a bit of Essence of Agony. Any old poison vendor should do.\n\nWe have a potion to make!", sourceObjective = "Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.", progress = "It will be ever so lovely to have our lost sheep returned to the fold, don't you think?", completion = "These will do nicely. We will see how much bravado our honored guest retains after he is subjected to my masterpiece.", sourceObjectiveStatus = "unverified-source-field" }
quests[97292] = { id = 97292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Torment", description = "I have concocted a lovely serum that our new guest is sure to find quite... stimulating.\n\nTake this. Feed it into the workings dripping from above him. Let's see if we can't show him why it's in his best interest to serve loyally.\n\nAnd try not to drop it. I can't afford a new assistant.", sourceObjective = "Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.", progress = "For Othmar's crimes against the Dark Lady, placing him under that oozing specimen is the least he deserves.\n\nAnd it's funny...", completion = "Excellent. We'll let his flesh simmer for awhile. Give him time to acclimate to his new home.\n\nI have no further use for the wretch for now, but we shall keep an eye on him. I have many plans for Othmar's future.", sourceObjectiveStatus = "unverified-source-field" }
quests[97326] = { id = 97326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocks to Rests", description = "Hey! You've got time to help us out! I know you do, I can tell by the way you smiled watching the game we're playing.\n\nThis spot behind Grommash Hold is nice because it's clear enough for us to set up our figures. But what stinks is we don't have enough rocks for chairs or tables.\n\nYou're big and strong... d'ya think you could carry back some medium sized rocks, smooth enough to sit on if we need a rest?", sourceObjective = "Return 8 Smooth Boulders to Thra behind Grommash Hold.", progress = "It's nice to not have to always sit in the dirt!", completion = "How can you even hold all of those boulders!\n\nThose are great. Most even have a nice flat side, too. Now that you carried them all the way over here we can scoot them around in the dirt, right where we want 'em.\n\nThanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[97328] = { id = 97328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything of Value", description = "<As you sift through the debris left behind by a horrible zeppelin crash directly above, you find evidence of a hefty shipment of supplies that has long since been plundered of all its value. Even the shipping labels have been torn and shredded, leaving only the words 'Booty Bay' barely legible on one.\n\nCountless two-toed footprints and several patches of divotted earth all lead toward ruins in the northwest.>", sourceObjective = "Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[97329] = { id = 97329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's the Key?", description = "You! Yes, you! Come here, keep your voice down!\n\nI screwed up big time. I managed to secure a sweet deal for Booty Bay to use their zeppelin tower for expedited deliveries and on our very first route I saw a huge bird--err, got SHOT DOWN just to the east of here!\n\nI survived the crash, unfortunately, but before I woke up, I was already being dragged by my ears! Now I'm surrounded by bloodthirsty trolls and locked in a cage!\n\nLook, I just need the key, okay? I can escape on my own.", sourceObjective = "Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark.", sourceObjectiveStatus = "unverified-source-field" }
quests[97331] = { id = 97331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zimmix's Great Escape", description = "Wait, wait, don't go yet!\n\nI know I said I just needed the key but... well, they caught me once, they could do it again, right? I'm just one goblin, and there's hundreds of trolls around here!\n\nYou've already put enough of a dent in their numbers to get this key, so it should be easy enough to stand guard while we mosey on out of here, huh?", sourceObjective = "Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue.", sourceObjectiveStatus = "unverified-source-field" }
quests[97485] = { id = 97485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traditions of the Bluff", description = "Blessings of An'she, friend.\n\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\n\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\n\nYou will find a mat and incense at the ceremonial site.", sourceObjective = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Ceder Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\n\nCombine the items and sprinkle the incense off of Hunter's Rise.", progress = "There are many occasions one may choose to spread incense to the winds. You could be asking the Earthmother to watch over someone, bless a hunt, celebrate an occasion, or even to seek guidance from our ancestors.\n\nOr it could be something else entirely.\n\nThough the act is done with reverence, it is not strictly a ceremonial affair. Typically there are certain traditional steps observed when performing this act, but many tribes have differing practices.", completion = "You have done well, friend.\n\nI thank you for taking the time to perform one of our time-honored traditions, {name}. I hope that as you travel you will find plenty of occasions you wish to give thanks for.\n\nShould you ever wish to perform the ritual again, you should be able to repurchase the components I sent you to collect.\n\nGo with An'she's warmth.", sourceObjectiveStatus = "unverified-source-field" }
quests[97538] = { id = 97538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pigments for Paints", description = "Greetings, friend. I wonder if I may ask a favor of you? I have just run out of red pigment for my paints, and I am looking for one with younger hooves to make the long journey into the Stonetalon Mountains on my behalf.\n\nIn the middle of the mountain pass there lies a large circular lake, Mirkfallon Lake, that has a unique plant that grows within its waters. The pods of this plant, mirkweed, turn a vibrant red when dried. Gather the pods of this plant for me, and I will reward you well for your efforts.", sourceObjective = "Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake.", progress = "You have returned! Were you able to find the mirkweed plant pods in Mirkfallon Lake?\n\nWe tauren have used this plant pigment in our paints for generations, so any amount you manage to bring would be appreciated. Though there are many ways to get a red pigment, I find the mirkweed to give the richest and most vibrant hue of the methods I'm familiar with.", completion = "Ah, thank you {name}.\n\nIt means much to me to have you venture all the way out there for what must seem a trivial notion from an old tauren, but with your kindness I will have enough pigment for the rest of the season.\n\nThank you for supporting my livelihood, and I will strive to create something magnificent with the pigments you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[97539] = { id = 97539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silky Sutures", description = "This encampment is being left to rot. The siege damage stands, unrepaired, as if neglect were policy. I won't permit that same decay here. The infirmary answers to me, and I intend to keep it functional.\n\nWe are nearly out of supplies. I'm going to need more equipment--enough to keep the workers and guards on their feet.\n\nUnder pressure, we can make quite an effective field suture using twisted spider silk.\n\n{class}, bring me some from the spiders that stalk these highlands.", sourceObjective = "Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[97558] = { id = 97558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hides for the Forsaken", description = "One part of undeath no one mentions is what happens when we are injured. How does the skin of an undead heal itself?\n\nWell, it doesn't.\n\nOurs is a cursed life, {name}. We must take from the living to further our own existence.\n\nWhen we sustain an injury, we must replace our skin which usually means animal hides. Since different hide thicknesses are better for different places on our bodies a variety is key!\n\nBring me wing membranes of a duskbat, hides from a darkhound and skin of a Vile Fin murloc.", sourceObjective = "Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.", progress = "Have you gathered the skin I inquired about? Our stocks are running low.\n\nIt may seem odd to ask for murloc skin but it works well for internal membranes, or surfaces like cheeks or mouths.\n\nSimilarly, the duskbat wing membranes are especially suited for more delicate areas, like faces or fingers. It prevents the skin from being too... thick.", completion = "Ah, excellent! Thank you for acquiring these. I can promise they will be put to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[97583] = { id = 97583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WRIGGLE.", description = "<The little slime seems delighted and is attempting to mirror your motions as you dance. It begins to look weary though.\n\nThe little slime hovers over a bit of sludge and absorbs it, looking slightly rejuvenated.\n\nIt seems all of this dancing has tuckered it out. Perhaps someone in the Undercity canals sells more of this nutritious sludge?>", sourceObjective = "Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention.", progress = "<The slime seems to regard you with interest.>", completion = "<The slime shudders with newfound energy. It seems to want to follow you, now that it has associated you with food.>", sourceObjectiveStatus = "unverified-source-field" }
quests[97891] = { id = 97891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prompt Potion Runner", description = "You! Quickly, I need you to bring this potion across the slime canal to Doctor Martin Felben in the Apothecarium!\n\nIt has a very limited shelf life, and no I can't go myself, my knees rattle and pop out if I attempt to run.\n\nJust another lovely side effect of undeath, apparently.\n\nBut we're wasting time! Here, take this and go!\n\n<Alessandro makes a shooing motion.>", sourceObjective = "Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit.", completion = "Ah, marvelous! I had been waiting for Alessandro's potion to arrive. The last six he sent destabilized along the way, but you've made it just in time!\n\nHere, take this for your effort. That is all for now, unless you have other business with me?\n\nIf not, remove yourself so I may continue my experiments unhindered.", sourceObjectiveStatus = "unverified-source-field" }
quests[97894] = { id = 97894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Business in Auberdine", description = "Pleasure to make yer acquaintance! Name's Borgus, of the one and only Steelhand family. You can always count on a Steelhand fer a fair deal!\n\nA few weeks back me brother Gorbold joined up with a merchant stall in Auberdine. Plenty of coin to be made supplyin' ships there, let me tell you! Lucky sod.\n\nI haven't heard from him since--mind checking on him if yer heading that way?\n\nThere's a new ship in the harbor that will take ye straight there. Head to the southern-most dock; can't miss it!", sourceObjective = "Check on Gorbold Steelhand in Auberdine in Darkshore.\n\nBorgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there.", completion = "Old Borgy sent you? Always looking out for me.\n\nWe could certainly use another set of hands around here. Business has all but stopped with the recent tragedy, and I think you could help set things right.", sourceObjectiveStatus = "unverified-source-field" }
quests[97899] = { id = 97899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Alchemy", description = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste.", sourceObjective = "Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There ya have it, directions for your very own Mana Well. Most folks don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to try it out.\n\nNo camp is complete without a campfire. You'll need one of those as the basis of your camp. Most cooks can teach you to make a fire. Check in with someone who can train you in cooking if you haven't already learned the basics.", sourceObjectiveStatus = "unverified-source-field" }
quests[97900] = { id = 97900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camping 101: Blacksmithing", description = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons.", sourceObjective = "Speak with Dwukk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", completion = "There you have it, you can now craft your very own Sharpening Wheel. Most folk don't care much for camps being set up in the center of town, so you'll need to head into the wilderness if you want to test it out.\n\nOh, and just remember, no camp is complete without a campfire. You'll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven't already, you might want to check in with someone who can train you in the culinary arts to learn the basics.", sourceObjectiveStatus = "unverified-source-field" }
